INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (1, N'ih0001', N'Bún lá mơ Vân Đình (Tên thường gọi khác: Bún rau mơ Vân Đình)', N'Van Dinh Skunkvine Noodle Soup (Alternative name: Van Dinh Stinkvine Noodles)', N'ritual', N'Bún lá mơ (hay bún rau mơ) là một món ăn sáng truyền thống đặc sắc và độc nhất vu nhị chỉ có tại Xóm 4 Thôn Vân Đình, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Đây là di sản thuộc loại hình tri thức dân gian, được truyền nối qua 3 đời trong gia đình bà Dương Thị Trinh. Món ăn mang hương vị vô cùng đặc biệt và kén người thưởng thức khi kết hợp vị ngọt thanh thuần túy từ nước cốt cua giã với rau mơ trắng luộc kỹ. Dù là một nét chấm phá ẩm thực độc đáo của đất Hà Thành, món ăn hiện đứng trước nguy cơ mai một lớn do phạm vi tiếp cận du khách còn hạn chế', N'Van Dinh skunkvine noodle soup (Bun la mo) is a unique and traditional breakfast dish found exclusively in Village 4, Van Dinh Commune, Ung Hoa District, Hanoi. As a piece of folk knowledge passed down through three generations in Ms. Duong Thi Trinh''s family, the dish offers a highly distinctive flavor that combines a pure, sweet crab broth with thoroughly boiled white skunkvine leaves. Although it represents a unique culinary highlight of Hanoi, this traditional dish currently faces a high risk of fading away due to its limited reach to tourists.', N'/uploads/images/9321ebd136f24aed8aa8dd654796ef78.jpg', NULL, 0, '2026-07-10T14:12:13.7758402', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Đang có nguy cơ mai một cao. Hiện tại toàn thôn chỉ còn đúng 2 nghệ nhân cũng là 2 người thực hành (hai chị em bà Dương Thị Trinh) duy trì nấu bán. Số lượng học viên hiện nay là 0 người do không có ai theo học, dẫn đến việc lan tỏa món ăn đến du khách còn gặp nhiều hạn chế.  Biện pháp & Đề xuất: Gia đình chủ thể vẫn luôn nỗ lực duy trì và thực hành nghề thường xuyên. Chủ thể đề xuất các cấp chính quyền đẩy mạnh công tác truyền thông, quảng bá thương hiệu ngay tại cơ sở, đồng thời có chính sách hỗ trợ tạo điều kiện cho hộ kinh doanh giới thiệu đặc sản này đến đông đảo du khách.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Kinh tế: Là nguồn thu nhập chính để nuôi sống gia đình chủ thể văn hóa (gia đình bà Dương Thị Trinh).  Văn hóa: Góp phần làm phong phú, đa dạng thêm cho di sản văn hóa ẩm thực độc đáo của thôn Vân Đình nói riêng và của Hà Nội nói chung.', NULL, NULL, NULL, N'Món ăn là tri thức dân gian gia truyền, được truyền lại từ đời cụ của bà Dương Thị Trinh và đã duy trì được 3 đời tại địa phương, trở thành món ăn sáng quen thuộc của người dân Xóm 4 Thôn Vân Đình.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The dish is a heirloom piece of folk knowledge passed down from the great-grandmother of Ms. Duong Thi Trinh. It has been maintained for three generations in the locality, serving as a familiar traditional breakfast for the residents of Village 4, Van Dinh Commune.', N'Economic Value: It serves as the primary source of income to support the family of the cultural practitioner (Ms. Duong Thi Trinh''s family).  Cultural Value: It enriches and diversifies the unique culinary heritage of Van Dinh Village in particular and Hanoi in general.', N'Current Status: The heritage is currently at a high risk of fading away. Currently, there are only 2 artisans who are also the only 2 practitioners (Ms. Duong Thi Trinh and her sister) maintaining the business. The number of current students is 0 because no one is learning the craft, which heavily limits the dish''s ability to reach outside tourists.  Measures & Proposals: The practitioner''s family always strives to maintain, practice, and pass down the craft''s knowledge on a regular basis. The main practitioner proposes that authorities at all levels should step up communication and promotional activities at the local level, and that the local government should provide supportive policies to help the household introduce this special dish to a wider audience of tourists.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (2, N'ih0002', N'Cá nướng Nghi Lộc (Cá nướng Thanh Nhàn)', N'Nghi Loc Roasted Fish (Thanh Nhan Roasted Fish)', N'ritual', N'Cá nướng Nghi Lộc là một tri thức dân gian và nét đẹp ẩm thực lâu đời của người dân thôn Nghi Lộc, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Theo phong tục truyền thống, cứ mỗi dịp Tết đến xuân về, các gia đình trong thôn đều chuẩn bị một phên cá nướng. Đặc biệt, từ ngày 20 tháng Chạp hàng năm, không khí làm nghề tại đây lại vô cùng nhộn nhịp để sản xuất hàng tấn cá cung cấp cho thực khách khắp cả nước. Món ăn nổi tiếng với quy trình chế biến công phu, kỹ thuật nướng củi suốt 36 tiếng đồng hồ, tạo nên hương vị đặc trưng, thịt cá dẻo, thơm thớ mà chỉ có tại thôn Nghi Lộc mới giữ được đúng "cái vị" chuẩn nhất.', N'Nghi Loc roasted fish is a long-standing culinary tradition and folk knowledge of the community in Nghi Loc Village, Van Dinh Commune, Ung Hoa District, Hanoi. According to local customs, every Tet holiday (Lunar New Year), every household in the village prepares a rack of roasted fish. Notably, from the 20th day of the last lunar month, the village becomes bustling to produce tons of fish for customers nationwide. This dish is famous for its elaborate preparation and a continuous 36-hour wood-firing technique, resulting in a uniquely fragrant, firm, and savory flavor that can only be authentically found in Nghi Loc Village.', N'/uploads/images/d17791119ba74ad4ae2ce3555a22b298.jpg', NULL, 0, '2026-07-10T14:28:11.5833180', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Di sản đang được duy trì tốt và không có nguy cơ mai một. Hiện tại làng nghề có 5 nghệ nhân (trong đó có 2 người có khả năng truyền dạy), 15 người thực hành và 5 học viên đang được truyền dạy theo phương thức "cầm tay chỉ việc".  Biện pháp & Đề xuất: Chủ thể vẫn thường xuyên chủ động truyền dạy kỹ thuật cho thế hệ kế cận. Đồng thời, nghệ nhân đề xuất thành lập Hợp tác xã chuyên sản xuất cá nướng và mong muốn chính quyền địa phương đẩy mạnh quảng bá thương hiệu, ban hành chính sách hỗ trợ phát triển sản xuất.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Kinh tế: Mang lại nguồn thu nhập chính và phát triển kinh tế ổn định cho các hộ gia đình chủ thể.  
Văn hóa: Góp phần làm phong phú, đa dạng và tôn vinh nét đẹp ẩm thực truyền thống độc đáo của thôn Nghi Lộc nói riêng và của đất Hà Thành nói chung.', NULL, NULL, NULL, N'Di sản đã có từ lâu đời, gắn liền với phong tục mỗi dịp Tết đến xuân về của người dân thôn Nghi Lộc. Hiện nay, nghề truyền thống này được duy trì và đại diện bởi bà Nguyễn Thị Nhàn cùng cộng đồng địa phương.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'This heritage has existed for generations, deeply intertwined with the traditional Tet holiday customs of the locals in Nghi Loc Village. Currently, this traditional craft is actively maintained and represented by Ms. Nguyen Thi Nhan and the local community.', N'Economic Value: It serves as the primary source of income, providing stable economic development for the practitioner''s family.  Cultural Value: It enriches, diversifies, and honors the unique traditional culinary beauty of Nghi Loc Village in particular and Hanoi in general.', N'Current Status: The heritage is well-maintained and faces no risk of fading away. The village currently has 5 artisans (including 2 capable of teaching), 15 active practitioners, and 5 apprentices being trained through hands-on practice.  Measures & Proposals: The main practitioner regularly maintains this folk knowledge and proactively teaches the techniques to the next generation. Additionally, the artisans propose establishing a cooperative specialized in roasted fish production and hope local authorities will boost brand promotion and issue supportive policies for production development.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (3, N'ih0003', N'Tri thức làm bánh cuốn Vân Đình', N'Folk knowledge of Van Dinh steamed rice roll making in Van Dinh Village, Van Dinh Commune.', N'ritual', N'Tri thức làm bánh cuốn Vân Đình là một nghề thủ công và nét đẹp ẩm thực truyền thống lâu đời được lưu giữ qua nhiều thế hệ tại thôn Vân Đình, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Nghề hiện được đại diện và duy trì bởi gia đình bà Nguyễn Thị Duyên với hơn ba thế hệ làm nghề. Điểm đặc sắc của bánh cuốn Vân Đình nằm ở sự tỉ mỉ trong từng công đoạn: từ khâu chọn duy nhất gạo Khang Dân xay bằng cối đá, kỹ thuật pha bột dựa vào cảm giác tay, cho đến kỹ nghệ tráng thủ công trên nồi hấp căng vải mỏng. Bánh đạt chuẩn có độ mỏng, dẻo, trắng trong, hòa quyện cùng nhân hành khô phi vàng giòn truyền thống, tạo nên một thương hiệu ẩm thực tinh tế đặc trưng của vùng đất Vân Đình.', N'The folk knowledge of Van Dinh steamed rice roll (Banh cuon) making is a long-standing traditional craft and culinary art preserved across generations in Van Dinh Village, Van Dinh Commune, Ung Hoa District, Hanoi. Today, it is actively maintained by Ms. Nguyen Thi Duyen''s family, spanning over three generations. The uniqueness of Van Dinh steamed rice rolls lies in the meticulousness of every step: from selecting solely Khang Dan rice to be ground on a stone mortar, to the intuitive dough-mixing technique, and the manual steaming process on a thin cloth-covered pot. The standard rolls are characterized by their thin, flexible, and translucent texture, perfectly paired with traditional crispy golden fried shallots, forming a signature culinary brand of the Van Dinh region.', N'/uploads/images/e757fdc09c8c4e458bead0ffb1df8c53.webp', NULL, 0, '2026-07-10T14:35:04.9329221', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Đang đứng trước nguy cơ mai một cao. Toàn địa phương hiện chỉ còn 1 nghệ nhân (bà Nguyễn Thị Duyên), 5 người thực hành và 2 học viên được truyền dạy nhỏ lẻ trong phạm vi gia đình. Người trẻ không mặn mà với nghề do công việc nặng nhọc, tốn thời gian, thu nhập bấp bênh và vấp phải sự cạnh tranh từ công nghệ chế biến hiện đại.

Biện pháp & Đề xuất: Hiện tại việc bảo tồn chủ yếu mang tính tự phát dựa trên kinh nghiệm truyền miệng gia đình. Chủ thể đề xuất chính quyền hỗ trợ kinh phí, công cụ và kết nối đầu ra; tổ chức các lớp truyền dạy bài bản; tăng cường quảng bá qua hội chợ ẩm thực và xây dựng mô hình trải nghiệm nghề gắn với phát triển du lịch văn hóa.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Góp phần bảo tồn bản sắc văn hóa ẩm thực truyền thống tinh tế, khéo léo của vùng đồng bằng Bắc Bộ và là niềm tự hào về thương hiệu ẩm thực đặc trưng của Vân Đình.

Kinh tế: Tạo sinh kế và nguồn thu nhập ổn định cho người dân địa phương làm nghề.', NULL, NULL, NULL, N'Là nghề truyền thống lâu đời được lưu giữ và thực hành qua nhiều thế hệ trong các gia đình ở địa phương. Hiện nay, gia đình bà Nguyễn Thị Duyên là một trong số ít hộ còn duy trì và truyền nối nghề qua hơn ba thế hệ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'A time-honored traditional craft preserved and practiced through multiple generations within local families. Currently, Ms. Nguyen Thi Duyen''s family is one of the very few households still preserving and passing down the trade for over three generations.', N'Cultural Value: Contributes to preserving the delicate and skillful traditional culinary identity of the Northern Delta, serving as a source of pride for Van Dinh''s signature gastronomy.

Economic Value: Provides a stable livelihood and income for local practitioners.', N'Current Status: Currently at a high risk of fading away. The locality currently has only 1 recognized artisan (Ms. Nguyen Thi Duyen), 5 active practitioners, and 2 apprentices being taught on a small scale within the family. The younger generation shows little interest due to the labor-intensive, time-consuming nature of the job, unstable income, and fierce competition from modern processing technologies.

Measures & Proposals: Safeguarding measures are currently spontaneous and rely heavily on oral transmission within families without official support. Proposals include financial support for raw materials and tools, establishing stable market distribution, organizing structured training classes for local youths, boosting promotion through food fairs, and creating community-based cultural tourism models.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (4, N'ih0004', N'Vịt cỏ Vân Đình.', N'Van Dinh Grass Duck (Van Dinh Grass Duck Culinary Heritage).', N'ritual', N'Vịt cỏ Vân Đình là một di sản thuộc loại hình tri thức dân gian ẩm thực nổi tiếng, gắn liền với giống vịt cỏ bản địa được chăn thả truyền thống trên các cánh đồng chiêm tại xã Vân Đình, huyện Ứng Hòa, Hà Nội. Sự kết hợp độc đáo giữa chất lượng thịt vịt, kinh nghiệm lựa chọn kỹ lưỡng và bí quyết chế biến phong phú (như nướng, luộc, om sấu, làm chả, nấu cháo...) đã đưa Vân Đình trở thành "thủ phủ vịt cỏ" vang danh khắp cả nước và quốc tế. Di sản hiện được đại diện bởi bà Nguyễn Thị Sinh với gia đình có 3 đời theo nghề, không chỉ mang lại giá trị kinh tế cao mà còn là một nét chấm phá đặc sắc, khẳng định thương hiệu đặc sản vùng miền của bản đồ ẩm thực Thủ đô.', N'Van Dinh Grass Duck represents a renowned intangible cultural heritage of folk culinary knowledge, deeply associated with the indigenous grass duck breed traditionally raised on the low-lying rice fields of Van Dinh Commune, Ung Hoa District, Hanoi. The unique combination of high-quality duck meat, meticulous selection experience, and diverse specialized cooking techniques (including grilling, boiling, sour dracontomelon stewing, duck patties, and porridge) has turned Van Dinh into the famous "grass duck capital" nationwide and internationally. Represented by Ms. Nguyen Thi Sinh, whose family spans three generations in the trade, this heritage not only provides substantial economic value but also serves as a brilliant highlight that asserts the signature regional brand of Hanoi''s gastronomy.', N'/uploads/images/e63f7bb4a9aa4a0b9ee71eebba17f4b9.webp', NULL, 0, '2026-07-10T14:37:54.6718379', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Di sản đang phát triển rất mạnh mẽ với lực lượng thực hành đông đảo bao gồm 7 nghệ nhân (đều có khả năng truyền dạy), 23 người thực hành và 12 học viên đang theo học theo phương thức "cầm tay chỉ việc".

Biện pháp & Đề xuất: Cộng đồng và các gia đình nghệ nhân tích cực duy trì thực hành thường xuyên, truyền dạy bài bản cho thế hệ kế cận. Đồng thời, chủ động mở rộng thị trường, đưa các sản phẩm ẩm thực từ vịt cỏ Vân Đình đi phân phối rộng khắp các tỉnh thành trong cả nước và xuất khẩu ra nước ngoài.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Kinh tế: Là nguồn thu nhập và sinh kế chính cho nhiều gia đình tại địa phương.

Văn hóa: Góp phần làm phong phú, đa dạng bản đồ di sản ẩm thực của Vân Đình nói riêng và thủ đô Hà Nội nói chung, khẳng định mạnh mẽ thương hiệu đặc sản vùng miền.', NULL, NULL, NULL, N'Bắt nguồn từ giống vịt cỏ bản địa chăn thả theo hình thức truyền thống trên các cánh đồng chiêm của Vân Đình. Tri thức chế biến được lưu truyền qua nhiều thế hệ, tiêu biểu như gia đình bà Nguyễn Thị Sinh đã có 3 đời liên tục duy trì và thực hành nghề.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Originates from the indigenous grass duck breed traditionally free-roamed on the low-lying rice fields of Van Dinh. The culinary knowledge has been passed down through generations, notably preserved by Ms. Nguyen Thi Sinh''s family for three consecutive generations.', N'Economic Value: Serves as the primary source of income and main livelihood for numerous local families.

Cultural Value: Enriches and diversifies the culinary heritage map of Van Dinh in particular and Hanoi in general, strongly asserting a signature regional specialty brand.', N'Current Status: Faces no risk of fading away. The heritage is thriving with a strong community of practitioners, including 7 recognized artisans (all capable of teaching), 23 active practitioners, and 12 apprentices currently undergoing hands-on training.

Measures & Proposals: The local community and artisan families actively maintain regular culinary practices and provide structured training for the next generation. Furthermore, they proactively expand their market reach, distributing Van Dinh grass duck products to various provinces across Vietnam and exporting them abroad.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (5, N'ih0005', N'Tập quán thờ cúng tổ tiên tại nhà thờ Tiến sỹ Mai Danh Tông', N'Ancestor worship practices at the Worship House of Doctor Mai Danh Tong', N'festival', N'Tập quán thờ cúng tổ tiên tại nhà thờ Tiến sỹ Mai Danh Tông là một di sản văn hóa phi vật thể thuộc loại hình tập quán xã hội và tín ngưỡng, ra đời từ đầu thế kỷ 18 và được dòng họ Mai duy trì liên tục cho đến nay tại thôn Cao Lãm, xã Cao Thành, huyện Ứng Hòa, Hà Nội. Di sản gắn liền với việc tri ân, tôn vinh cụ Mai Danh Tông – người đỗ Đồng tiến sỹ xuất thân khoa Tân Hợi (1731) và từng giữ chức Giám sát ngự sử đạo Kinh Bắc. Hàng năm, vào ngày Đại kỵ mùng 10 tháng Mười Âm lịch và các ngày lễ tiết khác, con cháu dòng họ từ khắp nơi lại tề tựu đông đủ để thực hiện các nghi thức tế lễ cổ truyền trang nghiêm như lễ cáo yết, đọc chúc văn bằng chữ Hán, và tế lễ 4 tuần (hương hoa, đăng rượu, đọc chúc, dâng trà) kết hợp cùng phường bát âm. Tập quán này không chỉ lưu giữ vẹn nguyên các giá trị nghi lễ truyền thống mà còn là sợi dây tâm linh bền chặt, củng cố sự đoàn kết dòng tộc và giáo dục thế hệ trẻ lòng biết ơn, hiếu học.', N'The ancestor worship practices at the Worship House of Doctor Mai Danh Tong is an intangible cultural heritage belonging to social practices and beliefs, originating in the early 18th century and continuously maintained by the Mai clan to this day in Cao Lam Village, Cao Thanh Commune, Ung Hoa District, Hanoi. This heritage is deeply tied to honoring Doctor Mai Danh Tong, who achieved the title of "Dong Tien sy xuat than" (Doctorate) in the Tan Hoi imperial examination (1731) and served as the Imperial Censor of Kinh Bac region. Annually, on the main death anniversary (the 10th day of the 10th lunar month) and other ritual days, clan descendants from various regions gather to perform solemn traditional rituals, including the announcement ceremony, the reading of the Hán-script oration, and a four-round ritual offering (incense/flowers, light/wine, oration reading, and tea dation) accompanied by traditional Bat Am music. This practice not only preserves traditional ritualistic values but also serves as a strong spiritual bond that strengthens family solidarity and educates the younger generation on gratitude and academic traditions.', N'/uploads/images/17e8027a2e2244e6a2333b6adddd26d5.png', NULL, 0, '2026-07-10T14:40:57.5890399', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Di sản hoạt động dựa trên tinh thần tự giác rất cao của dòng tộc với 2 nghệ nhân có khả năng truyền dạy, 50 người thực hành thường xuyên và 15 học viên trẻ tuổi đang tham gia kế cận.

Biện pháp & Đề xuất: Dòng họ hiện duy trì việc kể chuyện về thân thế, sự nghiệp của cụ tổ cho con cháu trong ngày giỗ Đại kỵ; phương thức truyền dạy chủ yếu là truyền khẩu (truyền miệng). Đồng thời, họ liên tục động viên và thu hút lực lượng thanh niên tham gia vào các công việc tế lễ, chuẩn bị hậu cần của dòng họ để đảm bảo tính kế thừa bền vững.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Lưu giữ các nghi lễ tế tự truyền thống, y phục cổ truyền (áo the, khăn xếp) và nghệ thuật diễn xướng (phường bát âm, đọc chúc văn chữ Hán), góp phần bảo tồn bản sắc văn hóa Việt.

Xã hội: Giúp các thế hệ nhớ về cội nguồn, củng cố tình cảm, sự đoàn kết và trách nhiệm trong gia tộc; giáo dục con cháu sống hướng thiện, biết ơn tổ tiên và phát huy truyền thống hiếu học.', NULL, NULL, NULL, N'Xuất hiện từ đầu thế kỷ 18 sau khi cụ Mai Danh Tông vinh quy bái tổ và cống hiến cho triều đình. Tập quán được thực hành liên tục và truyền nối theo nguyên tắc cha truyền con nối qua hơn 15 thế hệ, hiện do ông trưởng chi Mai Danh Thự trực tiếp trông coi và điều hành nghi lễ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Originated in the early 18th century following Doctor Mai Danh Tong''s academic success and service to the royal court. The practice has been passed down continuously through patriarchal succession for over 15 generations, currently overseen and managed by the head of the branch, Mr. Mai Danh Thu.', N'Cultural Value: Preserves traditional sacrificial rituals, traditional attires (ao the, khan xep), and performing arts (Bat Am music, Hán-script oration chanting), contributing to safeguarding Vietnamese cultural identity.

Social Value: Helps generations remember their roots, fosters affection, solidarity, and responsibility within the clan, and teaches descendants to live virtuously, respect ancestors, and promote the family''s academic legacy.', N'Current Status: Faces no risk of fading away. The heritage functions smoothly on a voluntary basis within the clan, featuring 2 capable teaching elders, 50 active practitioners, and 15 young apprentices participating in the succession line.

Measures & Proposals: The clan actively retells the life and career history of Doctor Mai Danh Tong to descendants during the main anniversary; the transmission method is primarily oral. Furthermore, they regularly encourage and engage the younger generation in ritual duties and logistical preparation to ensure sustainable preservation.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (6, N'ih0006', N'Nghề Mây tre đan truyền thống thôn Hoàng Dương', N'Traditional Rattan and Bamboo Weaving Craft of Hoang Duong Village', N'festival', N'Nghề mây tre đan truyền thống tại thôn Hoàng Dương là một di sản văn hóa phi vật thể lâu đời của cộng đồng người Kinh tại xã Vân Đình, huyện Ứng Hòa, Hà Nội. Gắn liền với truyền thuyết chia đôi cây tre đầy thú vị với làng Tử Dương xưa, người dân Hoàng Dương đã kế thừa phần gốc tre để chuyên tâm phát triển nghề làm các vật dụng gia đình như nong, nia, thúng, mủng, giần, sàng. Quy trình chế biến đòi hỏi sự tỉ mỉ và phân công lao động nhịp nhàng qua 6 công đoạn: từ chọn tre, chẻ nan hình xương cá diếp, vót cạp, đan lèn khít, đến lấn cạp và nứt cố định bằng sợi mây. Đặc biệt, làng nghề sở hữu kỹ thuật đan cải góc bàn cờ vô cùng độc đáo và kỳ công. Với tập tục sinh hoạt văn hóa đặc sắc gắn liền với phiên chợ cuối năm đền Xà Cầu, nghề không chỉ mang lại sinh kế vững vàng mà còn là niềm tự hào, sợi dây gắn kết bền chặt giữa các thế hệ trong dòng chảy văn hóa xứ Đoài.', N'The traditional rattan and bamboo weaving craft of Hoang Duong Village is a long-standing intangible cultural heritage of the Kinh ethnic community in Van Dinh Commune, Ung Hoa District, Hanoi. Deeply tied to an intriguing ancient legend of splitting a single bamboo tree with the neighboring Tu Duong Village, the artisans of Hoang Duong inherited the root part of the tree to specialize in crafting traditional household utensils such as flat winnowing baskets (nong, nia), baskets (thung, mung), and sieves (gian, sang). The production line requires meticulous care and smooth labor division across 6 main stages: from selecting the bamboo, splitting strips into a herring-bone shape, whittling frames, tightly weaving, to framing and binding with sturdy rattan fibers. Notably, the village possesses an incredibly unique and elaborate "chessboard corner-weaving" technique. Combined with unique cultural customs attached to the year-end market at Xa Cau Temple, this craft not only ensures a sustainable livelihood but also serves as a pillar of community pride and a tight bond between generations.', N'/uploads/images/0ef7c42fef134c0087a82bb25fbbd1e0.webp', NULL, 0, '2026-07-10T14:44:22.9181066', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Làng nghề đang phát triển rất ổn định với lực lượng thực hành đông đảo, bao gồm 40 nghệ nhân (đều có khả năng truyền dạy), 180 người thực hành thường xuyên và 50 học viên trẻ tuổi đang theo học.

Biện pháp & Đề xuất: Cộng đồng địa phương luôn chủ động, tích cực truyền dạy nghề bài bản cho thế hệ con cháu trong làng để tiếp tục bảo vệ, gìn giữ và phát huy tối đa giá trị của nghề thủ công truyền thống này.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Kinh tế: Duy trì sinh kế ổn định và thúc đẩy phát triển kinh tế cho cộng đồng địa phương.

Văn hóa & Xã hội: Gìn giữ bản sắc văn hóa truyền thống, tri thức dân gian đặc trưng; tăng cường sự gắn kết xã hội thông qua việc truyền nghề giữa các thế hệ, đồng thời khơi dậy tính sáng tạo và nâng cao lòng tự hào về làng nghề cổ truyền.', NULL, NULL, NULL, N'Nghề có từ lâu đời, gắn liền với tích cổ chia làng từ làng Gan Tía Hạ cũ: hai làng chia đôi cây tre, thôn Hoàng Dương nhận phần gốc nên làm các loại nong, nia, thúng, mủng, giần, sàng. Tri thức nghề được bảo tồn liên tục theo hình thức cha truyền con nối qua nhiều thế hệ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'A time-honored traditional craft rooted in an ancient village-splitting legend from the old Gan Tia Ha Village. When dividing a bamboo tree, Hoang Duong Village received the root section, which led to their specialization in making flat baskets, baskets, and sieves. The technical knowledge has been smoothly preserved through patriarchal succession over generations.', N'Economic Value: Sustains stable livelihoods and fosters local economic growth.

Cultural & Social Value: Safeguards traditional cultural identity and distinct folk knowledge; enhances social cohesion through intergenerational knowledge transmission, while stimulating creativity and reinforcing immense pride in the village''s craft.', N'Current Status: Faces no risk of fading away. The craft is thriving steadily with a robust community of practitioners, consisting of 40 recognized artisans (all capable of teaching), 180 active practitioners, and 50 young apprentices currently undergoing training.

Measures & Proposals: The local community proactively and dynamically passes down the craft to the younger generations in the village to continuously safeguard, maintain, and maximize the values of this traditional craftsmanship.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (7, N'ih0007', N'Lễ hội Tứ Xã.', N'Tu Xa Festival.', N'festival', N'Lễ hội Tứ Xã là một lễ hội truyền thống liên kết có từ xa xưa, từng được tổ chức luân phiên giữa 4 làng: Hoàng Xá, Lương Xá, Đình Tràng và Vân Đình thuộc khu vực Vân Đình, huyện Ứng Hòa, Hà Nội. Đây là ngày hội chung để thờ phụng các vị Thành hoàng làng, tiêu biểu như truyền thuyết về 3 anh em tam sinh (các vị tướng của Đinh Bộ Lĩnh) tại làng Vân Đình. Trải qua thời gian, do các biến động lịch sử, không gian liên kết chung và lễ hội Tứ Xã quy mô ngày xưa đã bị mai một hoàn toàn. Hiện nay, hoạt động này đã tách riêng về từng làng; mỗi nơi chỉ còn tự duy trì phần Lễ cốt lõi thu hẹp trong 3 ngày mà không còn giữ được phần Hội nhộn nhịp hay các nghi thức rước kiệu xoay vòng, trò chơi dân gian và nghệ thuật diễn xướng đặc sắc năm xưa.', N'The Tu Xa Festival is an ancient linked traditional festival that used to be held rotationally among four villages: Hoang Xa, Luong Xa, Dinh Trang, and Van Dinh in Van Dinh Commune, Ung Hoa District, Hanoi. It was a collective regional event dedicated to worshipping the Tutelary Gods of the four villages, notably including the legend of three triplet brothers (generations of generals under Emperor Dinh Bo Linh) in Van Dinh Village. Over time, this interconnected cultural space and the full-scale Tu Xa Festival have completely faded away. Currently, the shared celebration no longer exists; each village independently organizes its own scaled-down rituals lasting for 3 days, lacking the vibrant festive games, palanquin processions, and traditional performance arts of the past.', N'/uploads/images/0d2874b40cb042aa83a3e77b482495f5.jpg', NULL, 0, '2026-07-10T14:47:19.0880485', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Đã mai một hoàn toàn trên thực tế liên kết chung. Hiện tại không còn duy trì lễ hội chung giữa 4 làng; các số lượng về nghệ nhân, người thực hành, bài bản kỹ thuật và học viên đều bằng 0. Mỗi làng hiện tự tổ chức lễ thánh riêng theo quy cách nội bộ, phần Hội hầu như biến mất.

Biện pháp & Đề xuất: Việc truyền dạy nghi lễ nhỏ lẻ tại từng làng hiện do Hội Người cao tuổi đảm nhiệm chủ yếu bằng truyền miệng. Từ thực tế di sản chung không còn tồn tại, chủ thể văn hóa đưa ra đề xuất chính thức là đưa Lễ hội Tứ Xã ra khỏi danh mục kiểm kê di sản văn hóa phi vật thể', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Từng là biểu tượng cho tinh thần văn hóa, nhân văn sâu sắc; lưu giữ các đạo sắc phong quý giá (từ thời Cảnh Hưng 1784 và Quang Trung 1792) cùng các cổ vật như mũ thần, hia cổ.

Xã hội: Từng là dịp gặp mặt, đoàn tụ và gắn kết thiêng liêng của con em dân làng đang làm ăn sinh sống trên khắp mọi miền Tổ quốc.', NULL, NULL, NULL, N'Xuất hiện từ xa xưa trong lịch sử, là hình thức lễ hội liên làng gắn kết cộng đồng cư dân. Khi còn duy trì, lễ hội diễn ra vào trung tuần tháng Giêng hàng năm, kéo dài từ 5 đến 7 ngày và được quay vòng đăng cai giữa các làng (gọi là "Tam niên nhất lệ" do làng Đình Tràng không đủ điều kiện đăng cai).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Originated in ancient times as an inter-village festival format to consolidate community bonds. When it was active, the festival took place in the middle of the first lunar month, lasting 5 to 7 days, and rotated hosts among the villages (known as "Tam nien nhat le" since Dinh Trang Village was too small to host).', N'Cultural Value: Served as a profound cultural and humanistic symbol for future generations, preserving precious royal certificates (dating back to the Canh Hung era in 1784 and Quang Trung era in 1792) along with sacred artifacts like divine hats and ancient boots.

Social Value: Previously served as a sacred occasion for gatherings, reunions, and bonding among villagers living and working across different regions of the country.', N'Current Status: Completely faded away as a collective heritage. The joint festival is no longer maintained, and the numbers of artisans, active practitioners, structured repertoires, and apprentices have all dropped to 0. Each village now individualizes its rites, while the festive dynamic has nearly vanished.

Measures & Proposals: Internal ritual transmissions are handled by the local Association of the Elderly, mostly via oral methods. Given that the shared heritage no longer exists in reality, the cultural representatives have submitted an official proposal to remove the Tu Xa Festival from the intangible cultural heritage inventory list.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (8, N'ih0008', N'Hội làng tam thôn (Động Phí – Ngọc Động – Nguyễn Xá)', N'Tam Thon Village Festival (Dong Phi – Ngoc Dong – Nguyen Xa)', N'festival', N'Hội làng tam thôn là một lễ hội truyền thống liên làng đặc sắc có từ xa xưa, được lưu giữ qua nhiều thế hệ của nhân dân ba thôn Động Phí, Ngọc Động và Nguyễn Xá thuộc huyện Ứng Hòa, Hà Nội. Lễ hội được tổ chức định kỳ 3 năm một lần vào dịp Tết Nguyên đán (từ mùng 3 đến mùng 4 tháng Giêng) nhằm thờ phụng ba anh em vị thánh Bạch Tượng Huynh Công, Đệ Công và Tô Đài – những vị tướng có công lớn giúp Đinh Tiên Hoàng dẹp loạn 12 sứ quân, thống nhất đất nước vào thế kỷ thứ 10. Điểm độc đáo của lễ hội là hình thức luân phiên đăng cai tổ chức giữa ba làng với các nghi thức rước kiệu thánh tập trung vô cùng long trọng, các tập tục kiêng kỵ nghiêm ngặt và quy trình tế lễ cổ truyền trang nghiêm. Không chỉ bảo tồn hệ thống cổ vật đồ sộ gồm 30 đạo sắc phong, thần phả, lễ hội còn là ngày hội kết nối thiêng liêng, giáo dục tinh thần "uống nước nhớ nguồn" và thắt chặt tình làng nghĩa xóm bền chặt giữa ba thôn.', N'The Tam Thon Village Festival is a unique inter-village traditional festival originating in ancient times and preserved across generations by the residents of three villages: Dong Phi, Ngoc Dong, and Nguyen Xa in Ung Hoa District, Hanoi. Held triennially during the Lunar New Year (from the 3rd to the 4th day of the first lunar month), the festival worships three saint brothers—Bach Tuong Huynh Cong, De Công, and To Dai—who were 10th-century generals that made great contributions helping Emperor Dinh Tien Hoang suppress the 12 warlords rebellion and unify the country. The highlight of the festival is the rotational hosting system among the three villages, featuring grand collective palanquin processions, strict taboo practices, and solemn ancient sacrificial rituals. Aside from safeguarding a massive system of historical relics including 30 royal certificates and divine genealogies, the festival serves as a sacred bond that promotes the spirit of gratitude and reinforces the long-standing neighborly solidarity among the three villages.', N'/uploads/images/d5f699e86d1a4c8c9e05eb8914df4f50.png', NULL, 0, '2026-07-10T14:50:17.2515883', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Lễ hội đang duy trì rất tốt với lực lượng thực hành đông đảo gồm 4 nghệ nhân (3 người có khả năng truyền dạy), 200 người thực hành, 20 học viên kế cận và 50 người thuộc nguồn lực bảo vệ khác. Phương thức truyền dạy chủ yếu là truyền miệng.

Biện pháp & Đề xuất: Hiện tại, nhân dân địa phương tự nguyện đóng góp tiền của và công sức là chính, kết hợp với sự hỗ trợ một phần kinh phí từ chính quyền. Cộng đồng đề xuất các cấp tích cực tuyên truyền giá trị lễ hội cho thế hệ trẻ, đồng thời thực hiện ghi danh và có các chính sách hỗ trợ thỏa đáng cho các nghệ nhân có công bảo vệ, truyền dạy lễ hội.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Giáo dục tinh thần "uống nước nhớ nguồn", bày tỏ lòng biết ơn sâu sắc của dân làng đối với các bậc thánh thần có công với nước; lưu giữ các giá trị văn hóa cổ truyền qua hệ thống 30 đạo sắc phong, thần phả và các bài văn tế cổ.

Xã hội: Là sợi dây gắn kết tình cảm dòng tộc và cộng đồng, tạo cơ hội cho những người con xa quê trở về tụ họp, vui chơi và thắt chặt tình làng nghĩa xóm bền bỉ giữa ba thôn.', NULL, NULL, NULL, N'Xuất hiện từ xa xưa trong lịch sử để tưởng nhớ công ơn của các vị tướng thời Đinh. Lễ hội được bảo tồn liên tục qua nhiều thế hệ theo hình thức luân phiên, mỗi kỳ lễ hội sẽ do một trong ba thôn (Động Phí, Ngọc Động, hoặc Nguyễn Xá) đứng ra đăng cai tổ chức theo quy định bằng văn bản.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Formed in ancient times to commemorate the merits of the historical generals of the Dinh Dynasty. The festival has been consistently preserved across generations on a rotational basis; each festival edition is hosted by one of the three villages (Dong Phi, Ngoc Dong, or Nguyen Xa) according to written regulatory documents.', N'Cultural Value: Educates the public on the traditional spirit of gratitude ("when drinking water, remember its source"), showing deep respect toward national heroes, and preserving ancient cultural values through 30 royal certificates, divine genealogies, and classical orations.

Social Value: Strengthens community and familial emotional bonds, creating an ideal occasion for overseas or migrant villagers to return home, reunite, and tighten the close-knit neighborhood relationships between the three villages.', N'Current Status: Faces no risk of fading away. The festival is well-maintained with a strong practice community, including 4 recognized artisans (3 capable of teaching), 200 active practitioners, 20 apprentices, and 50 members in other safeguarding resources. The transmission method is primarily oral.

Measures & Proposals: Currently, local citizens voluntarily contribute most of the financial resources and labor, alongside partial funding support from local authorities. The community proposes that higher authorities step up promotional campaigns targeting the younger generation, officially register the heritage, and issue appropriate support policies for the artisans dedicated to protecting and teaching the festival traditions.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (9, N'ih0009', N'Hội làng Vĩnh Thượng', N'Vinh Thuong Village Festival', N'festival', N'Hội làng Vĩnh Thượng là một lễ hội truyền thống lâu đời của cộng đồng cư dân thôn Vĩnh Thượng, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Sau một thời gian bị gián đoạn do chiến tranh (1946 - 1989), lễ hội đã được khôi phục trang nghiêm từ năm 1990 nhằm tưởng nhớ và biết ơn 05 vị Thành hoàng làng. Được tổ chức định kỳ 4 năm một lần vào trung tuần tháng Hai Âm lịch (từ mùng 8 đến mùng 10), lễ hội quy tụ toàn bộ nhân dân tham gia vào không gian linh thiêng của đình làng và hệ thống 5 đền cổ kính. Điểm nhấn độc đáo của di sản nằm ở tục dâng lợn "Tố hảo", hội thi làm bánh dày nhuộm màu xanh lá chuối tinh tế, đặc biệt là tục "kết chạ" (kết nghĩa anh em) bền chặt với làng Áng Thượng qua nghi thức rước kiệu vượt sông. Lễ hội là cầu nối gìn giữ bản sắc văn hóa xứ Đoài, thắt chặt tinh thần đoàn kết liên làng và giáo dục thế hệ trẻ sống hiếu nghĩa, hướng thiện.', N'The Vinh Thuong Village Festival is a long-standing traditional festival of the local community in Vinh Thuong Village, Van Dinh Commune, Ung Hoa District, Hanoi. After a temporary disruption due to war (1946–1989), the festival was solemnly revived in 1990 to commemorate and express gratitude toward the 5 Tutelary Gods of the village. Held quadrennially in the middle of the second lunar month (from the 8th to the 10th day), the festival brings the entire community together within the sacred space of the communal house and its network of 5 ancient temples. The unique highlights of the heritage lie in the traditional "To hao" pig offering, the green banana-leaf-dyed Banh Day (round sticky rice cake) making competition, and notably, the deep-rooted fraternal connection ("ket cha") with the neighboring Ang Thuong Village through a cross-river palanquin procession ceremony. The festival serves as a cultural bridge preserving regional identity, fostering inter-village solidarity, and educating the younger generation on gratitude and moral virtues.', N'/uploads/images/22208dab1b57494cbc8b6f1f0b03e4d9.jpg', NULL, 0, '2026-07-10T14:54:37.4818032', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Di sản đang được thực hành và gìn giữ tốt với lực lượng tham gia đông đảo, bao gồm 2 nghệ nhân (1 người còn khả năng truyền dạy), 100 người thực hành thường xuyên (được phân vai cụ thể trong các đội tế nam, tế nữ, rước kiệu, nhạc lễ), 15 học viên trẻ tuổi và 30 người thuộc nguồn lực bảo vệ khác. Phương thức truyền dạy chủ yếu là truyền miệng.

Biện pháp & Đề xuất: Cộng đồng đề xuất nâng cao công tác tuyên truyền, giáo dục nguồn gốc lịch sử lễ hội cho thanh thiếu niên; tiến hành dịch nghĩa 18 bản sắc phong hiện có (từ triều Tây Sơn đến triều Nguyễn) để làm tư liệu nghiên cứu, giới thiệu đến đại chúng; đồng thời đảm bảo lễ hội diễn ra nghiêm túc với luật lệ các trò chơi dân gian rõ ràng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Giáo dục đạo lý "Uống nước nhớ nguồn", gìn giữ các phong tục tập quán cổ truyền, hệ thống 18 đạo sắc phong quý giá và các bài tế cổ; giúp duy trì trật tự, hiếu nghĩa và bảo tồn bản sắc văn hóa trước những ảnh hưởng của lối sống thực dụng thời hiện đại.

Xã hội: Thúc đẩy tinh thần đoàn kết cộng đồng sâu sắc, đặc biệt là mối quan hệ giao hảo kết chạ gắn bó keo sơn giữa hai làng bạn (Vĩnh Thượng và Áng Thượng).', NULL, NULL, NULL, N'Có từ lâu đời trong lịch sử và truyền qua nhiều thế hệ. Lễ hội từng bị gián đoạn từ năm 1946 đến năm 1989 do chiến tranh, sau đó được chính quyền và nhân dân khôi phục lại vào năm 1990 để duy trì việc thờ phụng đức Thành hoàng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Formed in ancient times and passed down through multiple generations. The festival was disrupted from 1946 to 1989 due to wartime conditions and was officially restored by local authorities and citizens in 1990 to maintain the worship of the Tutelary Gods.', N'Cultural Value: Educates the public on the traditional virtue of gratitude ("when drinking water, remember its source"), preserves historical customs, a collection of 18 royal certificates, and ancient sacrificial scripts; helps maintain moral order and familial respect while safeguarding cultural identity against the influence of modern pragmatic lifestyles.

Social Value: Deeply fosters community solidarity, particularly the strong, centuries-old fraternal alliance ("ket cha") between the two brotherly villages of Vinh Thuong and Ang Thuong.', N'Current Status: Faces no risk of fading away. The heritage is well-maintained with a massive practice community, including 2 recognized artisans (1 capable of teaching), 100 active practitioners (assigned to specific roles in male/female sacrificial teams, palanquin carriers, and ritual musicians), 15 young apprentices, and 30 members in other safeguarding resources. The transmission method is primarily oral.

Measures & Proposals: The community proposes to enhance promotional and educational campaigns about the festival''s historical origins for local youths; officially translate the 18 ancient royal certificates (ranging from the Tay Son Dynasty in 1796 to the Nguyen Dynasty in 1916) for research and public introduction; and ensure a well-organized festival environment with clear regulations for traditional folk games.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (10, N'ih0010', N'Hội làng Văn Ông', N'Van Ong Village Festival', N'festival', N'Hội làng Văn Ông là một lễ hội truyền thống có từ xa xưa của cộng đồng cư dân thôn Văn Ông, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Ngay cả trong thời kỳ chiến tranh khốc liệt, nhân dân địa phương vẫn kiên trì duy trì phần Lễ cốt lõi, và đến năm 1980, phần Hội đã chính thức được khôi phục, duy trì ổn định cho đến nay. Lễ hội được tổ chức định kỳ 3 năm một lần vào dịp đầu xuân (từ mùng 8 đến mùng 10 tháng Giêng Âm lịch) nhằm thờ phụng hai vị Thành hoàng làng là Thục Giang Đại Vương (tướng thời Hùng Vương) và Lý Sỹ Đại Vương (vị quan thời Lý có công chữa bệnh cứu người). Diễn ra trong không gian linh thiêng của Đình, Đền Thượng và Đền Hạ, lễ hội quy tụ các đội tế nam (đội tư văn) sắc xanh, đội tế nữ sắc vàng và đội phù giá áo lậu đỏ cùng tham gia hành lễ trang nghiêm. Với các tập tục độc đáo như dâng xỏ lợn đen do trai tráng nuôi dưỡng, làm bánh dày bánh tày chay, kết hợp cùng hội thi cây cảnh và các trò chơi dân gian đặc sắc, lễ hội là sợi dây gắn kết cộng đồng bền chặt và là minh chứng sâu sắc cho truyền thống "uống nước nhớ nguồn" của người dân nơi đây.', N'The Van Ong Village Festival is a time-honored traditional celebration of the local community in Van Ong Village, Van Dinh Commune, Ung Hoa District, Hanoi. Even during wartime, local residents persistently maintained the core rituals, and by 1980, the festive games and public activities ("Hội") were officially restored and have been steadily held ever since. The festival is organized triennially in early spring (from the 8th to the 10th day of the first lunar month) to worship two Tutelary Gods who rendered great services to the country and its people: Thuc Giang Dai Vuong (a general from the Hung King era) and Ly Sy Dai Vuong (a mandarin from the Ly Dynasty renowned for healing and saving lives). Taking place in the sacred spaces of the Communal House, Upper Temple, and Lower Temple, the festival brings together a male sacrificial team dressed in blue, a female sacrificial team in yellow, and a palanquin-bearing team in red ritual robes. Featuring unique customs such as offering a black pig''s head raised by local youths, preparing vegan round and square sticky rice cakes, alongside a bonsai competition and vibrant folk games, the festival serves as a powerful community bond and a profound testament to the traditional spirit of gratitude.', N'/uploads/images/e7e800f2625449308b9b517347747c58.webp', NULL, 0, '2026-07-10T14:57:36.9964770', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Lễ hội có lực lượng thực hành tương đối đông đảo với 2 nghệ nhân (1 người còn khả năng truyền dạy), 150 người thực hành trực tiếp (được phân vai chặt chẽ trong các ban khánh tiết, hương lão, đội tế nam, tế nữ, phù giá, sênh tiền), 20 học viên kế cận và 60 người thuộc nguồn lực bảo vệ khác. Phương thức truyền dạy chủ yếu là truyền miệng.

Biện pháp & Đề xuất: Hiện nay, lễ hội được duy trì chủ yếu nhờ nhân dân tự nguyện đóng góp kinh phí và nhiệt tình tham gia là chính, kết hợp với một phần hỗ trợ từ địa phương. Cộng đồng đề xuất cần tích cực tuyên truyền cho thế hệ trẻ tham gia; đồng thời thực hiện ghi danh và có chính sách hỗ trợ kịp thời đối với các nghệ nhân giữ vai trò truyền dạy lễ hội.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Thể hiện sâu sắc truyền thống "uống nước nhớ nguồn", lòng biết ơn tôn kính của dân làng đối với các bậc tiền nhân và thánh thần có công với nước, với dân.

Xã hội: Đóng vai trò là sợi dây gắn kết tình cảm thiêng liêng, tạo cơ hội lớn để nhân dân và con em trong làng tụ họp, củng cố tình đoàn kết, gắn bó cộng đồng.', NULL, NULL, NULL, N'Xuất hiện từ xa xưa trong lịch sử. Trải qua năm tháng và chiến tranh, dù các quán và văn chỉ cũ đã bị phá hủy khiến mọi hoạt động rước xách hiện nay tập trung tại đình, di sản vẫn được bảo tồn liên tục. Phần hội được khôi phục vững chắc từ năm 1980.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Originated in ancient times. Through the years and wars, although the old shrines ("quán") and literature stele houses were destroyed—causing all contemporary processions to focus entirely on the main communal house—the heritage has been continuously preserved. The festive activities were robustly revived in 1980.', N'Cultural Value: Deeply reflects the traditional virtue of gratitude ("when drinking water, remember its source"), demonstrating the villagers'' ultimate respect toward ancestors and deities who contributed to the nation and the community.

Social Value: Acts as a sacred emotional anchor, providing an ideal opportunity for villagers to gather, reunite, and reinforce local solidarity and community cohesion.', N'Current Status: Faces no risk of fading away. The festival maintains a strong practice community with 2 recognized artisans (1 capable of teaching), 150 active practitioners (strictly assigned to roles in the organizing committee, elderly council, male/female sacrificial groups, palanquin carriers, and Senh Tien musicians), 20 young apprentices, and 60 members in other safeguarding resources. The transmission method is primarily oral.

Measures & Proposals: Currently, the festival is sustained primarily through voluntary financial contributions and energetic participation from local citizens, along with partial funding support from local authorities. The community proposes to actively promote the festival''s values to the younger generation to encourage their participation, while officially registering the heritage and implementing timely support policies for the artisans dedicated to teaching the festival traditions.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (11, N'ih0011', N'Hội làng Vân Đình', N'Van Dinh Village Festival', N'festival', N'Hội làng Vân Đình là một lễ hội truyền thống lâu đời của cư dân vùng sông Đáy, gắn liền với tín ngưỡng thờ Thành hoàng làng tại thôn Vân Đình, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Lễ hội được tổ chức vào mùa xuân hằng năm (bắt đầu từ mùng 4 đến mùng 6 tháng Giêng) nhằm tôn vinh và tưởng niệm ba vị Đại vương Thượng đẳng thần là Chiêu Pháp, Đông Cự và Mộc Hoàn – những người con trai của làng đã có công theo Đinh Bộ Lĩnh dẹp loạn 12 sứ quân, dựng xây đất nước vào thế kỷ thứ 10. Trải qua những thăng trầm lịch sử và thời kỳ chiến tranh, người dân địa phương đã chủ động khôi phục lại trình tự nghi lễ trang nghiêm từ sau năm 1986. Điểm đặc sắc của di sản là nghi thức đại lễ rước kiệu quy mô lớn (định kỳ 5 năm một lần) qua hệ thống các ngôi đình cổ (đình Thượng, đình Ba, đình Trung) và quán Ông Đô, kết hợp cùng tục dâng cúng xôi gà gấc cài hoa hồng, đêm hát ca trù truyền thống và các trò chơi dân gian mang đậm tinh thần võ học vùng sông Đáy.', N'The Van Dinh Village Festival is a time-honored traditional celebration of the local community living along the Day River, closely tied to the custom of Tutelary God worship in Van Dinh Village, Van Dinh Commune, Ung Hoa District, Hanoi. Held annually in spring (from the 4th to the 6th day of the first lunar month), the festival honors and commemorates three supreme deities: Chieu Phap, Dong Cu, and Moc Hoan—three brave sons of Van Dinh who assisted Emperor Dinh Bo Linh in suppressing the 12 warlords rebellion to establish the nation in the 10th century. Despite historical disruptions during wartime, local residents proactively restored the solemn rituals following the Doi Moi (Renovation) period in 1986. The highlights of this heritage include a grand palanquin procession held quadrennially (every 5 years) across a network of ancient communal houses (Thuong, Ba, and Trung Communal Houses) and Ong Do Shrine, along with carefully prepared steamed momordica glutinous rice and chicken offerings, traditional Ca Tru singing nights, and folk games that reflect the martial spirit of the Day River region.', N'/uploads/images/76c5a751a15742e5a8c38def3b5a27e4.jpg', NULL, 0, '2026-07-10T15:02:34.4358708', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Có nguy cơ mai một phần nào. Dù có lực lượng tương đối mạnh với 30 nghệ nhân (20 người có khả năng truyền dạy), 300 người thực hành và đang dạy cho 300 học viên, nhưng di sản đang bị giảm lược nhiều nghi lễ cổ (mất hình thức rước nước, rước gà, rước văn, rước đường thủy). Lớp trẻ kế cận ít thông thạo cổ nhạc, chúc văn; thiếu tư liệu lưu trữ hệ thống và nguồn kinh phí hoàn toàn phụ thuộc vào sự tự nguyện của người dân.

Biện pháp & Đề xuất: Hiện tại nhân dân tự đóng góp kinh phí là chính. Cộng đồng đề xuất cần thực hiện ghi chép, quay phim, số hóa toàn bộ trình tự nghi lễ; mở các lớp truyền dạy chúc văn, nghi thức tế và hát ca trù cho thế hệ trẻ; tu bổ tôn tạo di tích đình, quán; đồng thời cấp kinh phí hỗ trợ định kỳ và tôn vinh các nghệ nhân có công.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Giúp người dân bày tỏ lòng biết ơn sâu sắc đối với tổ tiên, tưởng niệm Thành hoàng làng, khẳng định bản sắc văn hóa địa phương; đồng thời lưu giữ các giá trị nghệ thuật cổ kính như ca trù, âm nhạc tế thần và kiến trúc đình làng cổ.

Xã hội: Thắt chặt tình đoàn kết tinh thần trong cộng đồng xóm làng, khơi dậy tinh thần dẻo dai và thượng võ của người dân vùng sông Đáy dịp đầu xuân.', NULL, NULL, NULL, N'Xuất hiện từ lâu đời trong lịch sử, gắn liền với tiến trình lập làng và công trạng của các vị tướng thời Đinh. Lễ hội từng bị gián đoạn do chiến tranh và được nhân dân chủ động phục dựng, duy trì mạnh mẽ từ thời kỳ Đổi mới (sau năm 1986) dựa trên tinh thần tự quản của cộng đồng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Originated in ancient times, deeply rooted in the village''s foundation and the historical contributions of the Dinh Dynasty generals. Disrupted by past wars, the festival was voluntarily revived and maintained by local authorities and citizens after 1986 based on a self-governed community spirit.', N'Cultural Value: Allows residents to express their ultimate gratitude toward ancestors, commemorate the Tutelary Gods, and affirm local cultural identity; effectively preserves ancient artistic values such as Ca Tru singing, ritual music, and historical communal house architecture.

Social Value: Tightens spiritual solidarity and community bonds within the neighborhoods, while fostering the physical endurance and martial arts traditions of the Day River inhabitants during the New Year.', N'Current Status: Faces certain risks of fading away. Although it maintains a strong presence with 30 recognized artisans (20 capable of teaching), 300 active practitioners, and 300 young apprentices, the core rituals have been significantly simplified (completely losing the traditional water, chicken, literature, and water-route processions). The younger generation shows limited proficiency in ancient music and orations; systematic archives are lacking, and funding relies entirely on voluntary contributions.

Measures & Proposals: Currently sustained through voluntary funding by the villagers. The community proposes to record, film, and digitalize the entire sequence of rituals; open training classes for ritual orations, sacrificial rites, and Ca Tru singing for the youths; restore and protect local communal houses and shrines; and grant periodic financial support while honoring dedicated local artisans.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (12, N'ih0012', N'Hội làng Tử Dương', N'Tu Duong Village Festival', N'festival', N'Hội làng Tử Dương là một lễ hội truyền thống có từ lâu đời (hơn 100 năm) của cộng đồng cư dân thôn Tử Dương, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Sau các giai đoạn gián đoạn do chiến tranh, lễ hội đã được khôi phục trang nghiêm từ năm 1992 và duy trì định kỳ 3 năm một lần vào dịp Tết Nguyên đán (từ mùng 3 đến mùng 5 tháng Giêng). Lễ hội là không gian linh thiêng nhằm thờ phụng Đức Thành hoàng làng là Đệ Tam Hoàng Tử (Đại Long Quốc Vương) – một trong 100 người con của Lạc Long Quân và Âu Cơ, người có công đánh giặc, trị thủy và lập ấp dựng làng. Di sản sở hữu những nét kiêng kỵ đặc trưng độc đáo như không gọi tên "con trâu, con nghé", "quang gánh, gióng gánh", không dùng màu đỏ tuyền hay vàng tuyền. Điểm nhấn của lễ hội là lễ tế nhập tịch, quy trình rước oản quả nặng tới 100kg của các giáp về đình, nghi thức tế tại văn chỉ, cùng tục dâng cúng cơm cá chép rán và các trò chơi dân gian rộn ràng, mang đậm giá trị nhân văn và tinh thần kết nối dòng tộc.', N'The Tu Duong Village Festival is a time-honored traditional celebration with a history spanning over 100 years, maintained by the local community of Tu Duong Village, Van Dinh Commune, Ung Hoa District, Hanoi. Following historical disruptions caused by wars, the festival was solemnly revived in 1992 and is currently organized triennially during the Lunar New Year (from the 3rd to the 5th day of the first lunar month). The festival serves as a sacred space to worship the village''s Tutelary God—De Tam Hoang Tu (Dai Long Quoc Vuong), one of the 100 children of Lac Long Quân and Au Co during the 18th Hung King era, who rendered great services in fighting invaders, controlling water, and establishing the village. The heritage features unique and strict local taboos, such as forbidding the spoken names of "buffalo/calf" and "carrying poles/ropes," as well as banning pure red or pure yellow attires. The highlights of the festival include the entry ritual, the massive 100kg oản cake offerings processed by village hamlets to the communal house, sacred rites at the literature shrine, fried carp and rice offerings, and lively folk games that strengthen community cohesion.', N'/uploads/images/3ee130866c4f4eb0b8bbe741d58792f5.webp', NULL, 0, '2026-07-10T15:05:12.3791569', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Lễ hội duy trì lực lượng thực hành bài bản với 4 nghệ nhân (2 người còn khả năng truyền dạy), 150 người thực hành (phân vai nghiêm ngặt trong ban khánh tiết, hương lão, các đội tế nam áo xanh, tế nữ áo hồng, phù giá, sênh tiền, bát bửu, đội rồng), 20 học viên trẻ tuổi và 50 người thuộc nguồn lực bảo vệ khác. Phương thức truyền dạy là truyền miệng.

Biện pháp & Đề xuất: Hiện nay địa phương hỗ trợ một phần kinh phí, nguồn lực chính vẫn do nhân dân tự nguyện đóng góp và nhiệt tình tham gia. Cộng đồng đề xuất chính quyền các cấp tích cực tuyên truyền cho thế hệ trẻ về ý nghĩa của hội; thực hiện ghi danh và có các chính sách hỗ trợ cụ thể cho nghệ nhân truyền dạy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Giáo dục sâu sắc truyền thống "uống nước nhớ nguồn" của dân làng đối với các bậc thánh thần và tiền nhân có công lập làng; lưu giữ ngọc phả cổ cùng hệ thống 09 bản sắc phong kéo dài từ thế kỷ 16 đến thế kỷ 18.

Xã hội: Đóng vai trò là dịp để nhân dân trong làng và con em xa quê tụ họp, gặp gỡ giao lưu, thắt chặt và cố kết tình cảm cộng đồng tinh thần.', NULL, NULL, NULL, N'Có lịch sử lâu đời hơn một thế kỷ. Lễ hội từng bị gián đoạn trong những năm chiến tranh (1945 – 1956 và từ sau 1966). Sau khi hòa bình lập lại, di sản được nhân dân và chính quyền khôi phục vững chắc từ năm 1992, chuyển đổi từ hình thức tổ chức hàng năm sang định kỳ 3 năm một lần để đảm bảo tính trang trọng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Formed in ancient times with a history of more than a century. The festival faced various disruptions during wartime (1945–1956 and post-1966). Following the restoration of peace, it was firmly revived by local authorities and residents in 1992, transitioning from an annual event to a triennial schedule to ensure proper organization.', N'Cultural Value: Deeply instills the traditional philosophy of gratitude ("when drinking water, remember its source") toward deities and ancestors who founded the village; successfully preserves historical divine records and a collection of 09 photocopied royal certificates spanning from 1574 to 1793.

Social Value: Serves as a great opportunity for villagers and migrant descendants to gather, reunite, socialize, and reinforce regional solidarity and community bonding.', N'Current Status: Faces no risk of fading away. The festival maintains a highly structured practitioner framework consisting of 4 recognized artisans (2 capable of teaching), 150 active practitioners (strictly divided into roles such as male sacrificial teams in blue, female teams in pink, palanquin carriers, Senh Tien musicians, veterans handling the Eight Auspicious Weapons, and a dragon dance team), 20 apprentices, and 50 members in other safeguarding resources. The transmission method is strictly oral.

Measures & Proposals: Currently, the local government provides partial financial aid, while the main funding relies heavily on voluntary public contributions and enthusiastic citizen participation. The community proposes that higher authorities actively promote the festival''s historical significance to the younger generation, officially register the heritage, and implement specific support policies for teaching artisans.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (13, N'ih0013', N'Hội làng Thành Vật', N'Thanh Vat Village Festival', N'festival', N'Hội làng Thành Vật là một lễ hội truyền thống có lịch sử vô cùng lâu đời (khoảng 2000 năm) của cộng đồng cư dân thôn Thành Vật, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Lễ hội diễn ra vào mùa xuân hằng năm (từ mùng 4 đến mùng 8 tháng Giêng, chính hội vào mùng 6) nhằm thờ phụng và tưởng nhớ công lao của các vị thần: Đức Thái A, Đức Phủ Hộ, Đức Quý Minh đại vương, Mẫu Liễu Hạnh thủy thần, cùng Tiên sự loa tổ thị (người có công dạy dân làng nghề trồng dâu nuôi tằm). Di sản lưu giữ những nét văn hóa tâm linh đậm nét qua hệ thống thần phả từ thế kỷ 14 - 16 và tập tục tế "mạo huyết" (chôn lông và tiết lợn tế) vô cùng độc đáo để mô phỏng lại việc khao quân của các tướng lĩnh thời xưa. Với nghi thức đón tiếp và giao lưu giữa hai bên "Bố Mẹ" (thôn Áng Hạ và thôn Thành Vật) cùng chuỗi hoạt động rước chân nhang, tế thần trang nghiêm và các giải đấu thể thao sôi nổi, lễ hội là biểu tượng cho tinh thần gắn kết cộng đồng và truyền thống "uống nước nhớ nguồn" sâu sắc của địa phương.', N'The Thanh Vat Village Festival is a time-honored traditional celebration with a history spanning approximately 2,000 years, preserved by the local community of Thanh Vat Village, Van Dinh Commune, Ung Hoa District, Hanoi. Held annually in spring (from the 4th to the 8th day of the first lunar month, with the main festival on the 6th), the festival commemorates and honors the great contributions of various deities: Duc Thai A, Duc Phu Ho, Duc Quy Minh Dai Vuong, Mau Lieu Hanh (Water Goddess), and Tien su loa to thi (the ancestral founder who taught villagers sericulture and silk weaving). The heritage showcases profound spiritual values through divine genealogies dating back to the 14th and 16th centuries and the unique "Mao huyet" sacrificial custom (burying the fur and blood of the sacrificial pig) which replicates the ancient military tradition of feasting troops. Featuring a heartwarming welcoming and interaction ceremony with the honorary "Bo Me" (Parents) figures from Ang Ha and Thanh Vat villages, incense processions, and vibrant sports tournaments, the festival stands as a symbol of deep community bonding and gratitude.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', N'https://www.youtube.com/watch?v=C-bx4Qph--o', 0, '2026-07-10T15:07:34.8862836', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Lễ hội duy trì sức sống bền vững với lực lượng thực hành đông đảo, bao gồm 2 nghệ nhân có khả năng truyền dạy, 150 người thực hành (được phân vai cụ thể trong các đội tế nam, tế nữ, đội rước Mẫu, kiệu ông, đội lân), 20 học viên đang theo học và 60 người thuộc nguồn lực bảo vệ khác. Phương thức truyền dạy chủ yếu là truyền miệng.

Biện pháp & Đề xuất: Hiện tại, nguồn kinh phí tổ chức chủ yếu do nhân dân tự nguyện đóng góp và nhiệt tình tham gia là chính, kết hợp hỗ trợ một phần từ địa phương. Cộng đồng đề xuất cần tích cực tuyên truyền giá trị lễ hội cho thế hệ trẻ tham gia, đồng thời tiến hành ghi danh di sản và có chính sách hỗ trợ xứng đáng cho các nghệ nhân giữ vai trò truyền dạy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Thể hiện truyền thống tri ân "uống nước nhớ nguồn" sâu sắc đối với các bậc thánh thần và tổ nghề có công với dân với nước; bảo tồn các giá trị tư liệu cổ quý giá như thần tích, thần phả và các đạo sắc phong thời Lê, Nguyễn.

Xã hội: Tạo không gian linh thiêng và vui tươi để nhân dân tụ họp, gặp gỡ giao lưu, thắt chặt tình cảm gắn kết cộng đồng và mối quan hệ lân bang thân thiết (giữa hai thôn Thành Vật và Áng Hạ).', NULL, NULL, NULL, N'Có lịch sử lâu đời khoảng hai thiên niên kỷ, gắn liền với tiến trình lập làng, chống giặc ngoại xâm và phát triển ngành nghề truyền thống. Tiễn trình lễ hội được thực hiện nghiêm ngặt từ khâu họp ban tổ chức vào đầu tháng Chạp, lắp đặt kiệu (trồng kiệu) vào mùng 3 tháng Giêng, cho đến lễ tạ kết thúc vào mùng 8 tháng Giêng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Possesses an ancient history of around two millennia, closely linked to the village’s establishment, defense against invaders, and the inception of traditional occupations. The festival itinerary is strictly regulated, starting with organizing meetings in early December (lunar calendar), palanquin assembly ("trong kieu") on the 3rd day of the first lunar month, and concluding with a Thanksgiving ritual on the 8th day.', N'Cultural Value: Deeply instills the traditional virtue of gratitude ("when drinking water, remember its source") toward deities and craft ancestors; successfully safeguards precious historical items including divine genealogies and royal certificates from the Le and Nguyen Dynasties.

Social Value: Provides a sacred yet joyful gathering space for residents to meet, socialize, and reinforce community solidarity, while nurturing neighboring ties between Thanh Vat and Ang Ha villages.', N'Current Status: Faces no risk of fading away. The festival is stably sustained with a robust practice community, including 2 recognized teaching artisans, 150 active practitioners (strictly divided into male/female sacrificial teams, Mother Goddess palanquin carriers, male palanquin carriers, and a lion dance group), 20 active apprentices, and 60 members in other safeguarding resources. The transmission method is primarily oral.

Measures & Proposals: Currently funded mostly by voluntary public contributions and enthusiastic citizen participation, with partial aid from local authorities. The community proposes to actively promote the festival''s significance to the younger generation, officially register the heritage, and implement specific support policies for teaching artisans.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (14, N'ih0014', N'Hội làng Thanh Dương', N'Thanh Duong Village Festival', N'festival', N'Hội làng Thanh Dương (hay Lễ hội Ba Giang) là một lễ hội truyền thống liên làng có lịch sử lâu đời từ thời Hậu Lý – Tiền Lê, gắn liền với cộng đồng cư dân Kinh tại ba thôn: Giang Làng, Giang Soi và Giang Đường thuộc xã Vân Đình, huyện Ứng Hòa, Hà Nội. Lễ hội được tổ chức hằng năm từ ngày mùng 10 đến ngày 12 tháng Giêng Âm lịch (định kỳ 3 năm tổ chức hội lớn một lần) nhằm thờ phụng Thập đạo tướng quân – Đức vua Lê Hoàn tại cả ba ngôi đình của ba làng. Trải qua thời gian bị gián đoạn do chiến tranh, di sản đã được phục hồi vững chắc từ sau năm 1975 nhờ tinh thần tự quản và đóng góp tự nguyện của nhân dân. Điểm đặc sắc mang tính biểu tượng của lễ hội là quy trình rước kiệu xoay vòng cực kỳ chặt chẽ thể hiện tình anh em: ngày mùng 10 đón chân nhang rước thần về đình Giang Đường, ngày 11 di chuyển qua Bãi Đền rồi về đình Giang Soi, và ngày 12 làm lễ tế tạ bế mạc tại đình Giang Làng (đình anh Cả - Di tích lịch sử văn hóa cấp Quốc gia). Hòa quyện cùng không khí nghi lễ tế cộng đồng long trọng là các trò chơi dân gian như đi cà kheo, múa lân rồng, hát tuồng và hát chèo cổ, tạo nên một không gian văn hóa đầu xuân đặc sắc, gắn kết tình cảm xóm làng bền chặt.', N'The Thanh Duong Village Festival (popularly known as the Ba Giang Festival) is an ancient inter-village traditional celebration dating back to the Late Ly – Early Le Dynasties. It belongs to the Kinh ethnic community living across three connected villages: Giang Lang, Giang Soi, and Giang Duong in Van Dinh Commune, Ung Hoa District, Hanoi. Held annually from the 10th to the 12th day of the first lunar month (with a grand festival scale organized triennially), the festival venerates Supreme Commander Le Hoan (Emperor Le Hoan), enshrined as the Tutelary God in the communal houses of all three villages. Disrupted by past wars, the heritage was firmly revived after 1975 through community self-governance and voluntary public funding. The unique hallmark of this heritage lies in its tightly structured rotational procession that embodies fraternal unity: the deity is processed to Giang Duong Communal House on the 10th, moved through the Bai Den relic to Giang Soi Communal House on the 11th, and finally returned to Giang Lang Communal House (the eldest brother''s communal house—officially recognized as a National Historical-Cultural Relic) for the grand closing ceremony on the 12th. Blending solemn community sacrifices with lively folk games like stilt-walking, dragon dances, and traditional Tuong and Cheo singing, the festival serves as a vibrant early-spring cultural space that binds the neighborhood bonds.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T15:11:13.7762707', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Lễ hội đang duy trì sức sống mạnh mẽ với đội ngũ thực hành bài bản gồm 3 nghệ nhân (đều còn khả năng truyền dạy), 250 người thực hành trực tiếp (đội rước kiệu trai tân, đội rước rồng, đội bát biểu, đội em gái rước gươm hầu, các quan viên tế), 30 học viên kế cận và 100 người thuộc các nguồn lực bảo vệ khác. Phương thức truyền dạy chủ yếu là truyền miệng trực tiếp giữa các thế hệ.

Biện pháp & Đề xuất: Hiện tại nhân dân trong làng tự nguyện đóng góp phần lớn kinh phí tổ chức bên cạnh sự hỗ trợ hành lang pháp lý và một phần kinh phí của địa phương. Cộng đồng đề xuất chính quyền tích cực tuyên truyền cho thế hệ trẻ tham gia, đồng thời đề nghị ghi danh chính thức di sản và có chính sách hỗ trợ thỏa đáng cho các nghệ nhân có công truyền dạy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Thể hiện sâu sắc truyền thống “uống nước nhớ nguồn” của dân làng đối với các bậc thánh thần và tiền nhân có công với nước; lưu giữ hệ thống di sản cổ vật đồ sộ gồm 23 đạo sắc phong quý giá trải dài qua các triều đại phong kiến.

Xã hội: Tạo không gian văn hóa tinh thần vui tươi, lành mạnh đầu xuân; là dịp để nhân dân ba thôn liên kết tụ họp, gặp gỡ, cố kết tình cảm xóm làng và củng cố khối đoàn kết cộng đồng.', NULL, NULL, NULL, N'Xuất hiện từ thời Hậu Lý – Tiền Lê để tri ân công đức của Đức vua Lê Hoàn. Địa danh "Ba Giang" gắn liền với truyền thuyết về ba anh em: anh cả định cư ở Giang Làng, em thứ hai ở ven đường gọi là Giang Đường, và em út ở Giang Soi. Công tác chuẩn bị được thực hiện rất sớm từ ngày 20 - 25 tháng Chạp với sự họp bàn thống nhất của ba thôn, do thôn anh Cả (Giang Làng) chủ trì.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Originated during the Late Ly – Early Le Dynasties to commemorate the immense national merits of Emperor Le Hoan. The geographical name "Ba Giang" (Three Giangs) stems from a legend of three brothers: the eldest settled in Giang Lang, the second brother stayed by the roadside called Giang Duong, and the youngest established Giang Soi. Preparation begins early in the 12th lunar month, chaired by the eldest village (Giang Lang) to achieve community consensus.', N'Cultural Value: Deeply instills the traditional philosophy of gratitude ("when drinking water, remember its source") toward deities and historical national heroes; safeguards a vast historical collection of 23 royal certificates spanning various imperial reigns.

Social Value: Creates a joyful, wholesome spiritual environment during the Lunar New Year; serves as a great opportunity for the residents of the three villages to reunite, socialize, and strengthen regional solidarity and neighborhood bonds.', N'Current Status: Faces no risk of fading away. The festival maintains a highly structured and resilient practitioner framework consisting of 3 recognized teaching artisans, 250 active practitioners (unmarried male palanquin carriers, dragon dancers, weapon bearers, and ritual musicians), 30 apprentices, and 100 members in other safeguarding resources. The transmission is primarily handled through direct oral methods across generations.

Measures & Proposals: Currently sustained primarily by voluntary financial donations and enthusiastic citizen labor, with partial funding and administrative support from local authorities. The community proposes that higher authorities step up promotional campaigns targeting the younger generation, officially register the festival heritage, and implement fair support policies for teaching artisans.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (15, N'ih0015', N'Hội làng Thanh Ấm', N'Thanh Am Village Festival', N'festival', N'Hội làng Thanh Ấm là một lễ hội truyền thống lâu đời của cộng đồng cư dân tộc Kinh tại thôn Thanh Ấm, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Được khôi phục từ năm 1995 và tổ chức quy củ theo hương ước từ năm 2005 đến nay, lễ hội diễn ra trong 3 ngày vào đầu tháng Giêng Âm lịch (linh hoạt trong khoảng từ mùng 8 đến 16 tháng Giêng) nhằm thờ phụng hai vị Thành hoàng làng là Thánh mẫu Thoải Cung và Minh Phúc đại vương — vị tướng có công giúp vua Đinh Tiên Hoàng dẹp loạn 12 sứ quân. Lễ hội lưu giữ nguyên vẹn các nghi thức cổ xưa với điểm nhấn là quy trình rước kiệu xoay vòng trang nghiêm qua hệ thống đình, đền, chùa quanh làng, quy tụ hơn 200 người tham gia diễu hành (gồm các kiệu sắc, bát cống, kiệu thần, kiệu võng). Với các quy định kiêng cữ nghiêm ngặt cho đội tế nam, tế nữ và bầu không khí sinh hoạt văn hóa tinh thần sôi nổi, lễ hội là điểm tựa tâm linh vững chắc giúp thắt chặt tình đoàn kết xóm làng và giáo dục thế hệ trẻ nhớ về nguồn cội.', N'The Thanh Am Village Festival is a long-standing traditional celebration of the Kinh ethnic community in Thanh Am Village, Van Dinh Commune, Ung Hoa District, Hanoi. Revived in 1995 and organized systematically in accordance with village conventions since 2005, the festival takes place over 3 days in early spring (flexibly scheduled between the 8th and 16th days of the first lunar month). It aims to worship and commemorate two Tutelary Deities: Goddess Thaoi Cung (Thanh mau Thoai Cung) and Minh Phuc Dai Vuong—a historical general who assisted Emperor Dinh Tiên Hoang in suppressing the 12 warlords rebellion. The festival perfectly preserves its ancient practices, highlighted by a grand and solemn palanquin procession involving over 200 participants escorting 4 ceremonial palanquins (Imperial Certificate, Bat Cong, Divine, and Hammock palanquins) through the village''s communal house, temple, and pagoda. With strict traditional taboos for the male and female sacrificial teams and a vibrant community atmosphere, the festival serves as a solid spiritual anchor that tightens neighborhood solidarity and educates younger generations on their roots.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T15:17:39.6864572', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Di sản có sức sống tốt và bền vững với đội ngũ thực hành gồm 21 nghệ nhân hiện có (12 người còn khả năng truyền dạy), hơn 100 người thực hành trực tiếp (trai tịnh rước kiệu quan, các cụ bà rước kiệu mẫu và các thành viên đội tế), cùng 24 học viên trẻ tuổi đang theo học bằng phương thức truyền dạy trực tiếp.

Biện pháp & Đề xuất: Cộng đồng tiếp tục duy trì việc tổ chức lễ hội nghiêm túc theo đúng quy ước, hương ước văn hóa của làng; lựa chọn thời gian linh hoạt đầu xuân để toàn thể nhân dân và khách thập phương có thể tham gia đông đủ, vẹn toàn.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Mang ý nghĩa lịch sử văn hóa truyền thống sâu sắc, giúp lưu giữ 4 đạo sắc phong cổ cùng hệ thống nghi lễ tế nam, tế nữ nghiêm cẩn và các bài bản tế thần cổ truyền.

Xã hội: Thắt chặt tinh thần đoàn kết, keo sơn của sinh hoạt cộng đồng tinh thần; tạo cầu nối tâm linh để con em đi làm ăn xa luôn hướng về quê hương, gia đình dịp đầu xuân mới.', NULL, NULL, NULL, N'Có từ xa xưa trong lịch sử và được trao truyền qua nhiều thế hệ. Lễ hội gắn liền với truyền thuyết về tướng quân Minh Phúc đại vương từng đóng quân nghỉ một đêm và được Thánh mẫu hiển linh hiến kế đánh bại Đỗ Cảnh Thạc tại Trang Hoa Âm (làng Thanh Ấm ngày nay). Di sản được khôi phục mạnh mẽ từ năm 1995 và duy trì ổn định, đúng hương ước cho đến nay.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Formed in ancient times and passed down through generations. It is closely tied to the legend of General Minh Phuc Dai Vuong, who stationed his troops for a night and received a winning military strategy from Goddess Thoai Cung at Hoa Am Ward (present-day Thanh Am Village). The festival was firmly revived in 1995 and has been strictly maintained under local conventions.', N'Cultural Value: Carries profound historical and cultural values; helps safeguard 4 ancient royal certificates along with highly structured male and female sacrificial rituals and ancient divine orations.

Social Value: Deeply reinforces community solidarity and neighborhood cohesion; acts as a spiritual bridge connecting migrant workers and distant descendants back to their homeland during the Lunar New Year.', N'Current Status: Faces no risk of fading away. The heritage enjoys a vibrant and resilient status with 21 recognized local artisans (12 capable of teaching), over 100 active practitioners (including pure-hearted young men carrying the gods'' palanquins, village elders carrying the goddess''s palanquin, and sacrificial members), and 24 young apprentices learning through direct transmission.

Measures & Proposals: The community continues to organize the festival meticulously according to the local cultural conventions; selecting flexible dates in early spring ensures full participation from both villagers and tourists.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (16, N'ih0016', N'Hội làng Tảo Khê, thôn Tảo Khê', N'Tao Khe Village Festival', N'festival', N'Hội làng Tảo Khê là một lễ hội truyền thống lâu đời của cộng đồng cư dân thôn Tảo Khê, xã Vân Đình, huyện Ứng Hòa, Hà Nội, được khởi nguồn từ năm 1240 (năm Canh Tỵ) và trao truyền liên tục cho đến ngày nay. Lễ hội diễn ra vào ngày mùng 7 và mùng 8 tháng Giêng Âm lịch hằng năm nhằm thờ phụng hai vị Thành hoàng làng có công với dân với nước là ông Trần Vô và Trần Thông. Di sản được tổ chức trang nghiêm tại không gian văn hóa linh thiêng gồm Đình Tảo Khê, Miếu Thượng và Miếu Hạ dưới sự phối hợp của Ban khánh tiết, Hội người cao tuổi cùng các đoàn thể địa phương. Điểm nhấn độc đáo của lễ hội là quy trình hành lễ chặt chẽ: ngày mùng 7 làm lễ tế khai quang, rước bát hương và bài vị đức Thành hoàng từ miếu về đình; ngày mùng 8 tiến hành đại lễ tế chính hội với 3 tuần tế nghiêm cẩn trước khi rước thần hoàn cung. Hòa quyện vào phần lễ kính cẩn là không khí trẩy hội đầu xuân rộn ràng với các trò chơi dân gian như bịt mắt bắt dê, đập niêu, kéo co, bắt vịt trên sông và đi cầu đốt pháo. Lễ hội là sợi dây tâm linh bền chặt, thể hiện đạo lý "uống nước nhớ nguồn" và thắt chặt tinh thần đoàn kết của tình làng nghĩa xóm.', N'The Tao Khe Village Festival is a long-standing traditional celebration of the local community in Tao Khe Village, Van Dinh Commune, Ung Hoa District, Hanoi, which originated in the Canh Ty year of 1240 and has been continuously preserved to this day. Held annually on the 7th and 8th days of the first lunar month, the festival commemorates and honors two Tutelary Gods, Tran Vo and Tran Thong, who rendered great services to the community. The heritage is solemnly organized within a sacred cultural space comprising the Tao Khe Communal House, Upper Shrine, and Lower Shrine, under the joint coordination of the ritual committee, the elderly council, and local organizations. The highlight of the festival lies in its well-structured ritual timeline: on the 7th day, the opening and cleansing rites are performed followed by a procession escorting the deities'' incense burners and tablets from the shrine to the communal house; on the 8th day, the grand main sacrifice is carried out with three meticulous rounds of offerings before returning the deities to their permanent resting places. Blending with the reverent rituals is a festive spring atmosphere packed with traditional folk games such as blind man''s buff, pot-smashing, tug-of-war, duck catching on the river, and bridge-walking while lighting firecrackers. The festival acts as a firm spiritual anchor that reinforces the virtue of gratitude and tightens community bonding.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T15:21:03.4296216', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Di sản có sức sống tốt với đội ngũ thực hành gồm 3 nghệ nhân hiện có (1 người còn khả năng truyền dạy), 150 người thực hành trực tiếp (thuộc các đội tế nam mặc sắc xanh, đội rước kiệu), 20 học viên trẻ tuổi và 60 người thuộc các nguồn lực khác tham gia bảo vệ dựa trên phương thức truyền miệng.

Biện pháp & Đề xuất: Hiện tại, chính quyền địa phương tạo điều kiện hỗ trợ thêm một phần kinh phí, nguồn lực chính vẫn do nhân dân tự nguyện đóng góp và nhiệt tình tham gia. Cộng đồng đề xuất chính quyền cần tích cực tuyên truyền giá trị, ý nghĩa hội làng cho thế hệ trẻ; thực hiện ghi danh di sản và ban hành chính sách hỗ trợ thỏa đáng cho các nghệ nhân giữ vai trò truyền dạy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Giáo dục và phát huy mạnh mẽ truyền thống “uống nước nhớ nguồn” của dân làng đối với các bậc thánh thần; lưu giữ hệ thống tư liệu cổ quý giá gồm thần phả và các đạo sắc phong tinh tế của làng.

Xã hội: Tạo điều kiện và cơ hội lý tưởng để nhân dân trong làng cũng như con em xa xứ tụ họp về lại quê hương, gặp gỡ giao lưu và cố kết tình cảm xóm làng gắn bó dịp đầu năm.', NULL, NULL, NULL, N'Xuất hiện vào năm 1240 (thời Trần, năm Canh Tỵ) và tồn tại bền vững qua nhiều thế kỷ. Công tác quản lý và tổ chức lễ hội được phân công chặt chẽ bởi Trưởng thôn (Trưởng ban lễ hội) phối hợp cùng Ban khánh tiết, Hội người cao tuổi và các đoàn thể như Cựu chiến binh, Hội phụ nữ, Đoàn thanh niên. Lễ hội duy trì các nghi thức rước kiệu truyền thống do trai tân khỏe mạnh, gia đình không vướng tang bụi đảm nhiệm.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Established in 1240 (during the Tran Dynasty, the Canh Ty year) and successfully passed down through generations. Management and organization are systematically directed by the Village Head (Head of the Festival Committee) in cooperation with the ritual committee, the elderly council, and local organizations such as the Veterans'' Association, the Women''s Union, and the Youth Union. The traditional palanquin processions are proudly handled by healthy, unmarried young men whose families are free from mourning taboos.', N'Cultural Value: Deeply instills and promotes the traditional philosophy of gratitude ("when drinking water, remember its source") toward deities and historical figures; safely safeguards precious local archives including divine genealogies and ancient imperial certificates.

Social Value: Provides an ideal opportunity for villagers and migrant descendants to gather, reunite, socialize, and reinforce local solidarity and community bonding during the Lunar New Year.', N'Current Status: Faces no risk of fading away. The heritage enjoys a vibrant and resilient status with a practice community consisting of 3 recognized local artisans (1 capable of teaching), 150 active practitioners (including male sacrificial teams dressed in blue and palanquin carriers), 20 active young apprentices, and 60 members in other safeguarding resources practicing oral transmission.

Measures & Proposals: Currently, the local government provides partial financial aid, while the main funding relies heavily on voluntary public donations and enthusiastic citizen labor. The community proposes that authorities actively promote the festival''s values to the younger generation, officially register the heritage, and implement fair support policies for teaching artisans.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (17, N'ih0017', N'Hội làng Phí Trạch', N'Phi Trach Village Festival', N'festival', N'Hội làng Phí Trạch là một lễ hội truyền thống lâu đời và có sức sống vô cùng bền bỉ của cộng đồng cư dân thôn Phí Trạch, xã Vân Đình, huyện Ứng Hòa, Hà Nội. Lễ hội được tổ chức từ ngày mùng 8 đến mùng 10 tháng Hai Âm lịch (với chu kỳ đại lễ 5 năm một lần theo quy ước sửa đổi từ năm 2010) nhằm thờ phụng Đức Thành hoàng làng là sứ quân Ngô Xương Xí — vị thủ lĩnh có công dừng quân giúp dân chỉnh đốn phòng thủ, ổn định đời sống và xua đuổi giặc cướp thời tự chủ. Điểm đặc sắc nhất của di sản nằm ở nghi thức rước kiệu kết nối tâm linh độc đáo: rước Thành hoàng từ đình làng xuống miếu Quán Ông (nơi thờ Chúc Lâm Đại Đầu Đà) để biểu trưng cho cuộc hội ngộ giữa "người anh" (Thành hoàng) và "người em" (vị thần tại miếu) sau mỗi 5 năm. Với quy trình thực hành nghiêm cẩn từ lễ mộc dục, tục "quay kiệu" cầu phúc đầy náo nhiệt trên đường rước, kết hợp cùng các hoạt động tế nam, tế nữ, múa lân, di sản là cầu nối gắn kết thiêng liêng, thể hiện đạo lý "uống nước nhớ nguồn" sâu sắc của nhân dân địa phương.', N'The Phi Trach Village Festival is a time-honored traditional celebration with a highly resilient vitality, preserved by the local community of Phi Trach Village, Van Dinh Commune, Ung Hoa District, Hanoi. Held from the 8th to the 10th day of the second lunar month (with a grand festival scale organized quadrennially/every 5 years according to the village''s amended convention since 2010), the festival venerates the village''s Tutelary God—Warlord Ngo Xuong Xi, a prominent historical leader who stationed his troops here, helped the locals organize defenses, stabilized daily life, and drove away bandits during the autonomous era. The absolute highlight of the heritage lies in its unique spiritual procession: every five years, the Tutelary God is processed from the main communal house down to Quan Ong Shrine (where Chuc Lam Dai Dau Da is worshipped) to symbolize a sacred reunion between the "elder brother" (the Tutelary God) and the "younger brother" (the deity at the shrine). Blending rigorous rituals like the statue-bathing ceremony (Mộc dục) with spectacular, high-energy "palanquin spinning" (quay kiệu) practices on the roads to pray for blessings, the festival serves as a profound community bond and a testament to the local virtue of gratitude.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T15:23:29.1762446', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Lễ hội duy trì nội lực mạnh mẽ với đội ngũ thực hành gồm 21 nghệ nhân hiện có (18 người còn khả năng truyền dạy), 200 người thực hành trực tiếp (đội tế nam, tế nữ, đội rước, đội nhạc), và 22 học viên kế cận. Phương thức trao truyền chủ yếu thông qua truyền miệng và "cầm tay chỉ việc".

Biện pháp & Đề xuất: Hiện tại, nguồn kinh phí chủ yếu do nhân dân tự nguyện đóng góp và nhiệt tình tham gia tự quản. Cộng đồng đề xuất cần tích cực tuyên truyền ý nghĩa lễ hội cho các thế hệ mai sau hiểu và gìn giữ; đồng thời mong muốn Nhà nước có các chính sách hỗ trợ thiết thực để bảo vệ và phát huy tối đa giá trị văn hóa của hội làng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Giáo dục sâu sắc truyền thống "uống nước nhớ nguồn", tri ân công đức của các bậc thánh thần và tiền nhân có công bảo vệ nhân dân; bảo tồn các nghi thức tế lễ, tập tục "quay kiệu" độc đáo.

Xã hội: Thắt chặt tình cảm gắn kết ruột rà của nhân dân trong làng; là sợi dây tinh thần mãnh liệt khiến những người con xa quê, dù làm ăn ở tận vùng đất mũi Cà Mau, cũng đồng lòng quay trở về tụ họp, dự hội quê hương.', NULL, NULL, NULL, N'Xuất hiện từ rất lâu đời trong lịch sử và chưa từng bị gián đoạn ngay cả trong thời kỳ chiến tranh khốc liệt. Trước đây hội diễn ra hàng năm, nhưng từ năm 2010 được chuyển sang định kỳ 5 năm tổ chức đại lễ một lần. Công tác chuẩn bị được thực hiện bài bản thông qua họp liên tịch tại nhà văn hóa để phân công, tuyển chọn nhân sự tế, rước và bao sái không gian đình miếu trước ngày hội.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Formed in ancient times and has never been disrupted, even during fierce wartime periods. Previously organized as an annual event, it transitioned to a five-year grand cycle in 2010. Preparations are meticulously handled via joint meetings at the village cultural house to assign roles, select practitioners, and clean the sacred communal house and shrine areas prior to the event.', N'Cultural Value: Deeply instills the traditional philosophy of gratitude ("when drinking water, remember its source") toward deities and ancestors who protected the community; perfectly preserves ancient sacrificial rites and the unique palanquin-spinning customs.

Social Value: Strongly reinforces familial and community bonds among the villagers; acts as a powerful spiritual anchor that draws distant descendants—even those working as far away as Ca Mau Province—back home to celebrate their roots.', N'Current Status: Faces no risk of fading away. The heritage enjoys a vibrant and self-sustaining status with a practice community consisting of 21 recognized local artisans (18 capable of teaching), 200 active practitioners (assigned to male/female sacrificial teams, palanquin carriers, and musicians), and 22 young apprentices learning through oral transmission and direct hands-on guidance.

Measures & Proposals: Currently funded almost entirely through voluntary public donations and enthusiastic citizen self-governance. The community proposes to actively step up promotional campaigns regarding the festival''s significance for future generations, and expresses a wish for practical government support policies to effectively safeguard and promote the festival''s cultural values.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (18, N'ih0018', N'Hội làng Ngọ Xá', N'Ngo Xa Village Festiva', N'festival', N'Hội làng Ngọ Xá là một lễ hội truyền thống lâu đời của cộng đồng cư dân tộc Kinh tại thôn Ngọ Xá, xã Vân Đình, huyện Ứng Hòa, Hà Nội, được khởi nguồn từ năm 1827 và giữ vững sức sống liên tục qua các thời kỳ chiến tranh. Diễn ra từ ngày mùng 8 đến mùng 10 tháng Ba Âm lịch (định kỳ 3 năm tổ chức hội lớn một lần kể từ năm 2000), lễ hội là dịp để nhân dân phụng thờ Đức Thành hoàng làng Phan Hoàng Thụ — vị trưởng quan tài năng văn võ vẹn toàn dưới thời Hùng Hạnh Vương thứ 18, người có công lập ấp và thiết lập hành cung tại vùng đất này. Lễ hội lưu giữ nguyên vẹn hệ thống nghi lễ cổ xưa nghiêm ngặt như tục kiêng thịt chó, quy trình bao sái thần viện và lễ tế trang nghiêm tại đình Trung. Điểm nhấn rực rỡ của di sản là đoàn rước kiệu gồm kiệu ảnh Bác, kiệu di tích, bát bửu, kiệu vua bà, kiệu song loan và kiệu Thành hoàng với tục "kiệu xoay" đầy náo nhiệt trên đường di chuyển qua các không gian linh thiêng (đình Trung, đình Thượng, đền Quán Bà). Lễ hội hòa quyện giữa các nghi thức kính cẩn và các sinh hoạt hội hè sôi động như hát quan họ ao Quán Mẫu, múa lân, tạo nên biểu tượng văn hóa tinh thần cố kết xóm làng sâu sắc.', N'The Ngo Xa Village Festival is a time-honored traditional celebration preserved by the Kinh ethnic community in Ngo Xa Village, Van Dinh Commune, Ung Hoa District, Hanoi. Originating around 1827, the festival has been continuously maintained without any wartime disruptions. Held annually from the 8th to the 10th day of the third lunar month (with a grand festival scale organized triennially since 2000), the festival venerates the village''s Tutelary God—Phan Hoang Thu, a legendary commander gifted in both literature and martial arts during the 18th Hung Hanh Vương reign, who established the hamlet and founded the administrative palace here. The festival strictly preserves ancient customs and strict taboos, such as banning dog meat in offerings and meticulous cleaning rituals at Trung Communal House. The vibrant hallmark of the heritage lies in its grand procession featuring multiple ceremonial palanquins (including Uncle Ho''s portrait, relic certificate, Bat Buu, Goddess, Song Loan, and Tutelary God palanquins) performing high-energy "palanquin spinning" (kiệu xoay) on its way through sacred sites (Trung Communal House, Thuong Communal House, and Quan Ba Temple). Blending solemn rituals with joyful activities like Quan Ho duet singing at Quan Mau pond and dragon dances, the festival serves as a powerful symbol of community bonding.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T15:25:59.3384307', NULL, 2, NULL, NULL, NULL, N'Hiện trạng: Không có nguy cơ mai một. Lễ hội duy trì sức sống mãnh liệt với đội ngũ thực hành bài bản gồm 13 nghệ nhân hiện có (12 người còn khả năng truyền dạy), 250 người thực hành trực tiếp (đội kiệu trai tịnh, đội tế, đội múa lân, nhạc công) và 24 học viên kế cận. Phương thức trao truyền chủ yếu là truyền miệng và "cầm tay chỉ việc".

Biện pháp & Đề xuất: Hiện tại di sản được bảo tồn tốt bằng nguồn kinh phí tự quản do nhân dân chủ động đóng góp (thu cố định 200.000đ/hộ và kêu gọi xã hội hóa). Cộng đồng đề xuất các cấp ngành cần tích cực tuyên truyền cho thế hệ trẻ hiểu và tham gia; đồng thời mong muốn có các chính sách hỗ trợ cụ thể từ các cơ quan quản lý để bảo vệ và phát huy tối đa lễ hội làng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Văn hóa: Minh chứng sâu sắc cho đạo lý “uống nước nhớ nguồn”, tri ân công đức tiền nhân lập ấp; bảo tồn nghệ thuật rước kiệu xoay và các bài bản tế thần truyền thống.

Xã hội: Thắt chặt tình cảm gắn kết ruột rà của cộng đồng; là điểm tựa tâm linh linh thiêng khiến những người con xa quê hương, dù lập nghiệp ở tận đất mũi Cà Mau, cũng đồng lòng tụ họp về dự hội quê nhà dịp đầu xuân.', NULL, NULL, NULL, N'Có lịch sử lâu đời được ghi nhận từ khoảng năm 1827. Từ năm 2000, để đáp ứng đời sống tinh thần của nhân dân, làng đã chuyển đổi chu kỳ tổ chức đại lễ từ 5 năm một lần thành 3 năm một lần. Công tác tổ chức do Trưởng thôn và các tiểu ban phối hợp thông qua họp Hội nghị liên tịch tại nhà văn hóa thôn nhằm phân công và tuyển chọn các đội hình phục vụ nghiêm túc.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Possesses a documented history dating back to approximately 1827. In 2000, to fulfill the spiritual needs of the community, the grand festival cycle was changed from every five years to every three years. Organization is systematically directed through joint meetings at the village cultural house to form the steering committee, assign duties, and carefully select performing teams.', N'Cultural Value: Deeply demonstrates the traditional virtue of gratitude ("when drinking water, remember its source") toward ancestors who founded the land; successfully safeguards the dramatic palanquin-spinning techniques and ancient divine sacrificial traditions.

Social Value: Strongly reinforces local community cohesion; acts as a sacred spiritual anchor that calls upon distant descendants—even those living as far away as Ca Mau Province—to return home and celebrate their roots.', N'Current Status: Faces no risk of fading away. The heritage enjoys a vibrant and resilient status with a practice community consisting of 13 recognized local artisans (12 capable of teaching), 250 active practitioners (including pure-hearted palanquin carriers, sacrificial teams, dragon dancers, and traditional musicians), and 24 active young apprentices learning through oral transmission and direct hands-on guidance.

Measures & Proposals: Currently successfully self-sustained through voluntary public funding and local household contributions (a fixed fee of 200,000 VND per household plus optional sponsorships). The community proposes that authorities', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (19, N'ih0019', N'Lễ hội truyền thống thôn Nghi Lộc (Hội làng Nghi Lộc)', N'Nghi Loc Village Traditional Festival', N'festival', N'Lễ hội truyền thống thôn Nghi Lộc (xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể mang tính cộng đồng sâu sắc, được tổ chức thường niên từ ngày 11 đến 13 tháng Giêng Âm lịch (chính hội ngày 12, cứ 3 năm mở hội lớn một lần). Lễ hội là không gian tâm linh, văn hóa đặc sắc với các nghi thức trang trọng như lễ bao sái, lễ rước kiệu bát cống rước Tứ vị thành hoàng cùng Đức thánh Trần Hưng Đạo và Đức Tụ Thần, các buổi tế nam/tế nữ trang nghiêm và dâng cúng cỗ mặn, cỗ chay truyền thống. Phần hội rộn ràng với nhiều trò chơi dân gian như đánh đu, đập niêu, nấu cơm thi, góp phần thắt chặt tình đoàn kết và gắn kết tình cảm xóm làng.', N'Nghi Loc Village Traditional Festival (Van Dinh Commune, Hanoi) is a deep-rooted community intangible cultural heritage, held annually from the 11th to the 13th day of the first lunar month (the main festival is on the 12th, with a grand celebration every three years). The festival offers a unique spiritual and cultural space featuring solemn rituals such as the statue-washing ritual (bao sai), a grand palanquin procession to welcome the Four Earth Gods (Tu vi Thanh hoang), Saint Tran Hung Dao, and Saint Tu Than. It includes dignified male and female offering rituals alongside traditional food offerings. The festive section is vibrant with folk games like swinging, pot-smashing, and clay-pot cooking competitions, fostering community solidarity and connecting villagers worldwide.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T18:49:18.8042378', NULL, 2, NULL, NULL, NULL, N'Di sản hiện đang được bảo tồn tốt và không có nguy cơ mai một. Lễ hội duy trì được lực lượng thực hành đông đảo với khoảng 150 người thực hiện, 60 người tham gia bảo vệ, cùng Ban Khánh tiết, ban Hương lão và các đội hình rước, tế nam/nữ, đội rồng, đội trống được tổ chức bài bản. Hiện làng có 2 nghệ nhân nắm giữ bí kíp, trong đó 1 người vẫn đang tích cực truyền dạy trực tiếp cho khoảng 20 học viên theo phương thức truyền miệng. Tập tục kiêng kỵ độc đáo (như kiêng màu vàng tại Quán Mẫu) vẫn được người dân tự giác thực hiện nghiêm túc.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị tâm linh & tín ngưỡng: Đáp ứng nhu cầu thực hành tín ngưỡng, là nơi nhân dân bày tỏ lòng tôn kính, tưởng nhớ công đức của các vị thần và cầu mong bình an cho xóm làng.

Giá trị lịch sử & tư liệu: Lưu giữ các hiện vật, thần phả và sắc phong quý giá của các triều đại, khẳng định bề dày lịch sử và văn hóa của vùng đất.

Giá trị văn hóa & gắn kết cộng đồng: Tạo không gian văn hóa lành mạnh thông qua các trò chơi dân gian, hát sênh tiền; là sợi dây tinh thần gắn kết bền chặt các thế hệ dân làng, đặc biệt là những người con xa quê hương trở về nguồn cội.', NULL, NULL, NULL, N'Lễ hội làng Nghi Lộc có lịch sử lâu đời từ xa xưa, theo lời kể của các bậc cao niên trong làng thì hội đã tồn tại bền vững hơn 100 năm qua. Lễ hội gắn liền với tín ngưỡng thờ phụng Tứ vị thành hoàng bao gồm Tam Nhạc (Đông Nhạc, Tây Nhạc, Trung Nhạc) và Đức Quốc vương thiên tử Lã Nương (Thứ phi của vua Lý Thánh Tông, người có công đánh giặc Chiêm Thành). Sứ mệnh lịch sử, công đức đánh giặc và sự hóa thân của Đức Quốc Mẫu được lưu giữ trang trọng trong thần phả cùng hệ thống sắc phong tiêu biểu qua các triều đại phong kiến như Thiệu Trị, Khải Định, Cảnh Hưng, Minh Mệnh, Tự Đức, Chiêu Thông tại Đình Nghi Lộc.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The Nghi Loc Village Festival has a long history, preserved for over 100 years according to local elders. The festival is closely associated with the worship of the Four Earth Gods, including the Three Mountain Gods (East, West, and Central Nhac) and Queen Consort Trieu La Nuong (a concubine of King Ly Thanh Tong who famously defeated Champa invaders). Her historical achievements, contributions, and deification are documented in the sacred family annals (than pha) along with a rich collection of royal certificates (sac phong) from various feudal dynasties (Thieu Tri, Khai Dinh, Canh Hung, Minh Menh, Tu Duc, Chieu Thong) currently preserved at Nghi Loc Communal House.', N'Spiritual & Belief Value: Fulfills the community''s spiritual needs, serving as a sacred space for locals to express gratitude to the deities and pray for peace and prosperity.

Historical & Documentary Value: Preserves invaluable historical artifacts, divine annals, and royal certificates across dynasties, asserting the deep historical roots of the region.

Cultural & Community Bonding Value: Creates a wholesome cultural playground through traditional folk games and Senh Tien musical performances; acts as a powerful emotional bond connecting generations of villagers, especially expatriates returning to their roots.', N'The heritage is currently well-preserved with no risk of erosion. The festival maintains a strong group of practitioners with approximately 150 active participants, 60 protectors, alongside the organizing committee, village elders, and structured teams for palanquin processions, male/female rituals, dragon dances, and drumming. There are currently 2 master artisans holding traditional knowledge, one of whom is actively training about 20 apprentices through oral transmission. Unique taboos (such as avoiding the color yellow at Quan Mau) are strictly and voluntarily respected by the community.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (20, N'ih0020', N'Lễ hội truyền thống thôn Hoàng Dương (Hội làng Hoàng Dương)', N'Hoang Duong Village Traditional Festival', N'festival', N'Lễ hội truyền thống thôn Hoàng Dương (xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể đặc sắc có lịch sử lâu đời, được tổ chức 3 năm một lần vào ngày 12 và mùng 13 tháng Giêng Âm lịch (chính hội ngày 13). Lễ hội diễn ra tập trung tại đình làng, là nơi thực hành các nghi lễ tâm linh trang trọng nhằm tưởng nhớ hai vị Thành hoàng làng có công dẹp giặc cứu nước. Lễ hội nổi bật với các tập tục dâng cúng xỏ lợn đen độc đáo, cỗ chay truyền thống, hội bình thơ đầu xuân, lễ tế bán dạ xuyên đêm và lễ tế dâng hương trang nghiêm của các đội tế nam, tế nữ. Phần hội rộn ràng với các trò chơi dân gian như đập niêu, bắt vịt, kéo co, chấm thi cây cảnh đẹp, góp phần thắt chặt tình đoàn kết và gắn kết cộng đồng trong thôn', N'Hoang Duong Village Traditional Festival (Van Dinh Commune, Hanoi) is a unique intangible cultural heritage with a long history, held every three years on the 12th and 13th days of the first lunar month, with the main festival falling on the 13th. Centered around the village communal house, the festival features solemn spiritual rituals dedicated to the two Tutelary Gods who historical protected the country from invaders. The event is highly distinguished by its unique offerings of black pig heads and traditional vegetarian cakes, springtime poetry recitations, late-night midnight rituals (te ban da), and respectful offering ceremonies performed by male and female ritual teams. The festive activities are vibrant with folk games such as pot-smashing, duck-catching, tug-of-war, and a beautiful ornamental plant competition, fostering solidarity and community bonding within the village.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T18:51:21.3374749', NULL, 2, NULL, NULL, NULL, N'Di sản hiện đang được bảo tồn rất tốt trong cộng đồng và không có nguy cơ bị mai một. Lễ hội duy trì được lực lượng thực hành đông đảo và bài bản với sự tham gia chủ chốt của Ban Khánh tiết, ban Hương lão cùng 150 người thực hành trực tiếp (bao gồm đội tế nam, tế nữ, đội sênh tiền) và 60 người bảo vệ. Hiện nay làng có 3 nghệ nhân, trong đó có 1 người còn khả năng và đang tích cực truyền dạy trực tiếp theo phương thức truyền miệng cho 20 học viên. Các tập tục kiêng kỵ về cúng tế và quy trình nuôi lợn đen dâng lễ của thanh niên từ 18-30 tuổi vẫn được duy trì nghiêm túc nối tiếp qua các thế hệ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị văn hóa tâm linh: Đáp ứng nhu cầu đời sống tinh thần của nhân dân, là dịp để dân làng thể hiện lòng biết ơn, tri ân sâu sắc đối với công đức dẹp giặc cứu nước của các vị Thành hoàng làng, cầu mong quốc thái dân an.  

Giá trị lịch sử & tư liệu: Lưu giữ các tư liệu sắc phong cổ qua các triều đại phong kiến, minh chứng cho bề dày lịch sử và tiến trình phát triển thăng trầm cùng dòng chảy lịch sử dân tộc của địa phương.  

Giá trị gắn kết cộng đồng: Khơi dậy nét đẹp văn hóa thông qua câu lạc bộ hát dân ca và hội bình thơ mừng xuân của "làng Chùa". Các trò chơi dân gian và nghi thức lễ hội góp phần tạo không gian vui chơi đầu xuân lành mạnh, thắt chặt tình làng nghĩa xóm.', NULL, NULL, NULL, N'Lễ hội làng Hoàng Dương có từ xa xưa với lịch sử khoảng hơn 100 năm. Do ảnh hưởng của chiến tranh, lễ hội từng bị gián đoạn từ năm 1954 đến năm 1979 và chính thức được khôi phục lại từ năm 1980 đến nay. Lễ hội gắn liền với tín ngưỡng thờ phụng hai vị Thành hoàng làng có công dẹp giặc cứu nước là: Cao Minh Hoằng Thánh Long Ứng Cương Nghị Linh Ứng Đại Vương (Trần Cao Minh) và Trung Liêm Dự Thính Đôn Tín Phổ Duệ Linh Ứng Đại Vương (Trần Trung Liêm). Dấu tích lịch sử của di sản hiện còn được ghi nhận qua 14 bản sắc phong phôtô (bản gốc đã mất) lưu giữ tại đình làng, mang các niên hiệu cổ như Cảnh Hưng thứ 44 (1783) và Khải Định thứ 9 (1924).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The Hoang Duong Village Festival originated in ancient times, with a history spanning over 100 years. Due to wartime disruptions, the festival was suspended from 1954 to 1979 and was officially revived in 1980. The festival is deeply associated with the worship of two Tutelary Gods who defeated enemies to save the nation: Cao Minh Hoang Thanh Long Ung Cuong Nghi Linh Ung Dai Vuong (Tran Cao Minh) and Trung Liem Du Thinh Don Tin Pho Due Linh Ung Dai Vuong (Tran Tran Liem). The historical remnants of the heritage are captured through 14 photocopied royal certificates (the originals have been lost) preserved at the communal house, bearing ancient reign eras such as Canh Hung 44th (1783) and Khai Dinh 9th (1924).', N'Spiritual and Cultural Value: Satisfies the local community''s spiritual needs, providing an occasion for villagers to express deep gratitude to the Tutelary Gods for saving the nation, while praying for peace and prosperity.  

Historical and Documentary Value: Preserves ancient royal certificates across feudal eras, serving as evidence of the rich history and historical evolution of the locality alongside national history.  

Community Bonding Value: Promotes cultural beauty through the local folk singing club and the traditional springtime poetry festival of "Chua village". The traditional folk games and festival rituals offer a wholesome recreational space for early spring, strengthening neighborly bonds.', N'The heritage is currently exceptionally well-preserved within the community and faces no risk of erosion. The festival maintains a large, well-organized practice force with the pivotal leadership of the Organizing Committee and village elders, alongside 150 active practitioners (including male and female ritual groups and the Senh Tien musical team) and 60 protectors. The village currently boasts 3 master artisans, one of whom is actively passing down traditional knowledge via oral transmission to 20 apprentices. Strict taboos regarding ritual offerings and the rotating responsibility of youth aged 18–30 to rear black pigs for the deities continue to be diligently maintained across generations.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (21, N'ih0021', N'Lễ hội truyền thống thôn Hoàng Xá (Hội làng Hoàng Xá)', N'Hoang Xa Village Traditional Festival', N'festival', N'Lễ hội truyền thống thôn Hoàng Xá (xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể lâu đời, diễn ra thường niên từ ngày 14 đến 16 tháng Giêng và các ngày từ 19 đến 21 tháng 8 Âm lịch. Lễ hội được tổ chức tập trung tại đình làng nhằm phụng thờ Quý Minh đại vương – vị tả tướng của Hùng Duệ Vương có công dẹp giặc cứu nước. Sự kiện quy tụ các nghi lễ tâm linh độc đáo như lễ mộc dục dùng nước giếng làng và chóe cổ, lễ rước kiệu bát cống và kiệu thần vào ban đêm, cùng các tuần tế trang nghiêm của ban tế lễ. Phần hội diễn ra sôi động với nhiều trò chơi dân gian như đánh đu, tổ tôm điếm, chọi gà, múa sư tử và các đêm biểu diễn nghệ thuật truyền thống (chèo, tuồng, ca trù), tạo nên không gian gắn kết sâu sắc cho người dân và những người con xa quê.', N'Hoang Xa Village Traditional Festival (Van Dinh Commune, Hanoi) is a long-standing intangible cultural heritage held annually from the 14th to the 16th day of the first lunar month and from the 19th to the 21st day of the eighth lunar month. Centered at the village communal house, the festival venerates Quy Minh Dai Vuong, the Left General of King Hung Due Vuong who historically protected the country. The event features unique spiritual rituals, including the statue-washing ceremony (moc duc) using village well water and ancient jars, a mystical nighttime procession with two eight-bearer palanquins, and solemn offering rituals. The festive section is vibrant with folk games like swinging, To Tom Diem (card game), cockfighting, lion dances, and evening performances of traditional arts (Cheo, Tuong, Ca tru), creating a deeply bonding space for locals and expatriates.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T18:53:44.1872312', NULL, 2, NULL, NULL, NULL, N'Di sản đang được bảo tồn tốt trong đời sống hiện đại và không có nguy cơ mai một. Việc duy trì tổ chức lễ hội đã được cộng đồng thống nhất đưa vào Quy ước chính thức của làng. Lực lượng thực hành lễ hội rất đông đảo và quy củ với sự điều phối của chính quyền địa phương, Hội người cao tuổi cùng 150 người thực hành trực tiếp (bao gồm ban tế lễ 17 người mặc trang phục áo thụng mũ hia bài bản) và 50 người tham gia bảo vệ. Hiện làng có 2 nghệ nhân còn khả năng và đang thực hiện truyền dạy trực tiếp cho 20 học viên theo phương thức truyền miệng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị nhân văn & giáo dục: Là phương thức gìn giữ cội nguồn hiệu quả, giáo dục lòng biết ơn và truyền thống uống nước nhớ nguồn cho thế hệ trẻ qua hình tượng vị thần có công với đất nước.  

Giá trị lịch sử & tư liệu cổ: Lưu giữ hệ thống sắc phong quý hiếm, đặc biệt là sắc phong thời vua Quang Trung (1792), giữ vai trò là nguồn sử liệu chân thực về đời sống văn hóa, chính trị của địa phương qua các thời kỳ phong kiến.  

Giá trị nghệ thuật & gắn kết cộng đồng: Bảo tồn các loại hình nghệ thuật sân khấu cổ truyền (chèo, tuồng, ca trù) và các trò chơi dân gian đặc sắc. Đây đồng thời là dịp gặp mặt, hội ngộ ý nghĩa của những người con làng Hoàng Xá đang sinh sống và làm việc trên khắp mọi miền Tổ quốc.', NULL, NULL, NULL, N'Lễ hội làng Hoàng Xá có từ xa xưa và được lưu truyền qua nhiều thế hệ. Tâm điểm tâm linh của lễ hội gắn liền với vị nhân vật thờ phụng là Quý Minh đại vương — vị thánh thứ 3 trong Tản Viên Sơn Thánh và là vị tả tướng tài ba thời Hùng Vương thứ XVIII (Hùng Duệ Vương). Bề dày lịch sử và công đức của thần được ghi chép trang trọng trong thần phả, đồng thời được chứng thực qua 9 đạo sắc phong quý giá còn lưu giữ tại đình. Trong đó, đạo sắc phong cổ nhất mang niên hiệu "Quang Trung ngũ niên" (năm 1792) thuộc triều Tây Sơn, và 8 đạo sắc phong còn lại thuộc triều Nguyễn. Do tôn kính ngài, toàn thể dân làng từ xưa đến nay đều thực hiện tập tục kiêng kỵ đọc và dùng hai chữ "QUÍ" và "MINH", khi cần đều nói chệch thành "QUẾ" và "MIÊNG".', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The Hoang Xa Village Festival originated in ancient times and has been passed down through generations. The spiritual core of the festival is dedicated to Quy Minh Dai Vuong—the third deity of the Tan Vien Mountain Saints and a talented Left General during the reign of the 18th Hung King (King Hung Due Vuong). The rich history and divine merits of the deity are solemnly recorded in the divine annals (than pha) and authenticated by 9 precious royal certificates (sac phong) kept at the communal house. Among them, the oldest dates back to the "Quang Trung 5th year" (1792) under the Tay Son dynasty, while the remaining 8 certificates belong to the Nguyen dynasty. Out of ultimate respect, the villagers observe a unique taboo against using the words "QUY" and "MINH" in both rituals and daily life, intentionally mispronouncing them as "QUE" and "MIENG".', N'Humanistic & Educational Value: Serves as an effective way to preserve roots, educating the younger generation about gratitude and patriotism through the imagery of the national historic deity.  

Historical & Documentary Value: Preserves a rare system of royal certificates, especially the one from the King Quang Trung era (1792), acting as authentic historical records of the local cultural and political life during feudal times.  

Artistic & Community Bonding Value: Safely safeguards traditional theatrical arts (Cheo, Tuong, Ca tru) and distinctive folk games. It is also a meaningful annual gathering occasion for Hoang Xa descendants living and working across all regions of the country.', N'The heritage is currently well-preserved in modern life and faces no risk of erosion. The continuous organization of the festival has been officially incorporated into the village''s formal Convention (Quy uoc). The festival boasts a large and well-organized force coordinated by local authorities, the Elderly Association, alongside 150 active practitioners (including a 17-member ritual team fully costumed in traditional robes and ceremonial boots) and 50 protectors. The village currently has 2 master artisans who actively pass down traditional knowledge to 20 apprentices through oral transmission.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (22, N'ih0022', N'Lễ hội truyền thống thôn Hậu Xá (Hội làng Hậu Xá)', N'Hau Xa Village Traditional Festival', N'festival', N'Lễ hội truyền thống thôn Hậu Xá (xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể lâu đời của dân tộc Kinh, diễn ra 2 kỳ trong năm: lễ chay (Chính hội) vào mùng 3 tháng 2 Âm lịch và lễ mặn (Giỗ Thánh) vào mùng 10 tháng Chạp Âm lịch. Lễ hội được tổ chức tập trung tại đình làng Hậu Xá nhằm phụng thờ vị nhân thần thời Lý là Vũ Danh Phục, một vị quan võ có công với dân với nước. Di sản quy tụ nhiều nghi lễ nghiêm cẩn như lễ mộc dục bằng nước mưa nguyên chất, cúng oản nếp cái hoa vàng, các buổi tế yết và tế chính trang nghiêm kéo dài qua 8 tuần tế. Định kỳ từ 3 đến 5 năm, làng tổ chức lễ rước kiệu hoành tráng kết hợp múa sư tử. Phần hội diễn ra sôi động với các hoạt động kéo co, đu quay, múa rồng, văn nghệ quần chúng và đặc sắc nhất là hội "vật lễ" (vật thờ) truyền thống cho cả nam và nữ, góp phần thắt chặt tình làng nghĩa xóm và gìn giữ bản sắc quê hương.', N'Hau Xa Village Traditional Festival (Van Dinh Commune, Hanoi) is a long-standing intangible cultural heritage of the Kinh ethnic group, observed twice a year: the vegetarian offering (Main Festival) on the 3rd day of the second lunar month and the savory offering (Deity''s Death Anniversary) on the 10th day of the twelfth lunar month. Centered at Hau Xa Communal House, the festival venerates Vu Danh Phục, a historical military official from the Ly Dynasty with great merits to the country and its people. The heritage features meticulous rituals including a statue-washing ceremony (moc duc) using pure rainwater, traditional sweet rice cake (oan) offerings, and solemn rituals spanning 8 elaborate sessions. Every 3 to 5 years, a grand palanquin procession accompanied by lion dances is performed. The festive section is vibrant with tug-of-war, swinging, dragon dances, community performances, and most distinctively, the traditional "vat le" (ritual wrestling) for both men and women, reinforcing neighborly bonds and preserving cultural identity.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T18:56:07.4563129', NULL, 2, NULL, NULL, NULL, N'Di sản đang được bảo tồn ổn định trong đời sống cộng đồng và không có nguy cơ mai một. Lực lượng thực hành lễ hội duy trì khoảng 100 người bao gồm ban tế lễ (12 nam giới), các đội rước cờ, trống, bát bửu và múa sư tử. Làng hiện có một đội ngũ đông đảo với khoảng 30 - 40 nghệ nhân còn khả năng truyền dạy tốt và nắm giữ 30 - 40 bài bản cổ. Hiện tại có 15 học viên đang theo học, phương thức truyền dạy chủ yếu là truyền miệng, cầm tay chỉ việc kết hợp với sách vở ghi chép. Các quy ước nghiêm khắc như xử phạt người làm sai khi tế, hay kiêng người có tang bụi tham gia đội tế vẫn được người dân tuân thủ tự giác.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị nhân văn & đạo đức: Thể hiện sâu sắc đạo lý "Uống nước nhớ nguồn" của dân tộc, là nơi nhân dân bày tỏ lòng thành kính, tri ân vị anh hùng có công với nước, qua đó giáo dục văn hóa ứng xử tốt đẹp cho thế hệ trẻ.  

Giá trị lịch sử & tư liệu cổ: Lưu giữ và khôi phục thành công hệ thống sắc phong, di vật quý hiếm từ thế kỷ XVII, đóng vai trò quan trọng trong việc nghiên cứu lịch sử phong kiến và tín ngưỡng thờ nhân thần tại địa phương.  

Giá trị thể thao & gắn kết cộng đồng: Bảo tồn trò chơi "vật lễ" (vật thờ) độc đáo mang tính biểu tượng cao (nam tế thần, nữ tế mẫu), khơi dậy tinh thần thượng võ. Đồng thời, đây là sợi dây thắt chặt tình làng nghĩa xóm, củng cố mối quan hệ kết nghĩa gắn bó giữa các địa phương.', NULL, NULL, NULL, N'Lễ hội làng Hậu Xá xuất hiện từ trước thế kỷ XIX và được lưu truyền bền vững qua nhiều thế hệ. Trong kháng chiến chống Pháp, lễ hội từng bị gián đoạn một thời gian do đình, đền bị bắn phá. Tâm điểm tâm linh của di sản gắn liền với việc thờ phụng Thành hoàng làng là Vũ Danh Phục (Thuận Thế chiếu ứng sắc sinh thần đại vương), vị nhân thần thời vua Lý Nhân Tông và Lý Anh Tông. Bề dày lịch sử của ngôi đình gắn với các di vật quý từ thế kỷ XVII. Dù từng bị mất trộm 10 đạo sắc phong, dân làng đã nỗ lực thỉnh lại được 4 đạo sắc phong và sao chép số còn lại từ Viện nghiên cứu Hán Nôm để tiếp tục phụng thờ. Để bày tỏ lòng tôn kính, dân làng giữ tập tục nghiêm ngặt kiêng gọi trực tiếp tên của Thành hoàng làng, các chữ tên Thánh đều phải viết trại đi ngay cả trong văn tế.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The Hau Xa Village Festival originated prior to the 19th century and has been sustainably preserved through generations, despite a temporary suspension during the anti-French resistance war due to shellings on the communal house and temple. The spiritual core of the heritage is dedicated to the village Tutelary God, Vu Danh Phuc (Thuan The chieu ung sac sinh than dai vuong), a historic human deity during the reigns of Kings Ly Nhan Tong and Ly Anh Tong. The historical depth of the communal house is reflected in its precious 17th-century artifacts. Although 10 royal certificates were once stolen, the villagers managed to retrieve 4 and made copies of the rest from the Institute of Han-Nom Studies for ongoing worship. Out of utmost reverence, the community observes a strict taboo against speaking the Tutelary God''s real name, intentionally altering the characters even within ceremonial orations.', N'Humanistic & Ethical Value: Deeply reflects the traditional Vietnamese ethos of "When drinking water, remember its source," acting as a platform for locals to express gratitude to historical heroes while educating the youth on moral behaviors.  

Historical & Documentary Value: Successfully preserves and restores 17th-century historical artifacts and royal certificates, playing a crucial role in researching feudal history and local human deity worship.  

Sporting & Community Bonding Value: Safeguards the unique "vat le" (ritual wrestling) with high symbolic meaning (naked men wrestling to offer to gods, women to mothers), fostering a martial arts spirit. It serves as a vital bond tightening community solidarity and local sisterhood relationships.', N'The heritage is stably preserved within the community and faces no risk of erosion. The festival maintains around 100 active practitioners, including a 12-member male ritual team, procession teams for banners, drums, and historical weapons (bat buu), and lion dancers. The village boasts a strong group of 30 to 40 master artisans capable of training and holding 30 to 40 traditional repertoires. There are currently 15 apprentices being trained through oral transmission, hands-on guidance, and written records. Strict rules, such as penalizing ritual errors or prohibiting those in mourning from joining the ritual team, are voluntarily and closely respected by the residents.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (23, N'ih0023', N'Lễ hội truyền thống thôn Đông Dương (Hội làng Đông Dương)', N'Dong Duong Village Traditional Festival', N'festival', N'Lễ hội truyền thống thôn Đông Dương (xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể mang tính cộng đồng sâu sắc, có lịch sử lâu đời và được tổ chức lớn 5 năm một lần trong 3 ngày, từ mùng 10 đến 12 tháng Giêng Âm lịch. Lễ hội là không gian tâm linh, văn hóa đặc sắc nhằm phụng thờ nhị vị Đương cảnh thành hoàng bao gồm Đô Minh Vương và Đương Cảnh thành hoàng. Di sản quy tụ nhiều nghi lễ nghiêm cẩn như lễ bao sái long ngai bằng nước giếng sắc hòa nước thơm, lễ rước thần hội đồng hoành tráng bằng 4 kiệu bát cống từ các miếu đền về đình làng, cùng các buổi tế yết, tế chính hội và tế tạ trang nghiêm. Phần hội diễn ra rộn ràng với các trò chơi dân gian như đi cầu phao, đập niêu, kéo co, bắt vịt kết hợp với đêm văn nghệ quần chúng và hát quan họ trên thuyền, hát chèo đầu xuân, góp phần cố kết tình cảm xóm làng và kết nối những người con xa quê.', N'Dong Duong Village Traditional Festival (Van Dinh Commune, Hanoi) is a deep-rooted community intangible cultural heritage with a long history, celebrated on a grand scale every five years for three days, from the 10th to the 12th day of the first lunar month. The festival serves as a unique spiritual and cultural space to venerate the two local Tutelary Gods, namely Do Minh Vuong and Duong Canh Thanh Hoang. The heritage features meticulous rituals including a statue-washing ceremony (bao sai) using well water mixed with aromatic water, a grand grand procession with 4 eight-bearer palanquins bringing the deities from various shrines to the central communal house, and solemn offering ceremonies. The festive section is vibrant with folk games like walking on a floating bridge, pot-smashing, tug-of-war, and duck-catching, combined with community art exchanges, Quan ho singing on boats, and Cheo singing, strengthening neighborhood bonds and connecting expatriates.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T18:57:55.9576103', NULL, 2, NULL, NULL, NULL, N'Di sản đang được bảo tồn rất ổn định trong đời sống hiện đại và không có nguy cơ mai một. Lực lượng thực hành lễ hội duy trì quy mô đông đảo với khoảng 150 người thực hành và 60 người hỗ trợ bảo vệ. Các đội hình được tổ chức bài bản bao gồm Đội tế nam (24 bô lão từ 60-70 tuổi trở lên đảm bảo tiêu chuẩn "sạch"), Đội rước kiệu bát cống (16 nam thanh niên từ 18-30 tuổi chưa vợ), Đội sênh tiền (12 người) và Đội múa lân (8 người). Hiện làng có 2 nghệ nhân, trong đó có 1 người còn khả năng và đang tích cực truyền dạy trực tiếp theo phương thức truyền miệng cho 20 học viên.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị văn hóa tâm linh: Giáo dục sâu sắc truyền thống "Uống nước nhớ nguồn" của dân tộc, là dịp để nhân dân bày tỏ lòng tôn kính, tri ân sâu sắc đối với công đức của các vị thần và cầu mong bình an cho xóm làng.  

Giá trị lịch sử & tư liệu cổ: Lưu giữ 11 đạo sắc phong cổ và ngọc phả quý hiếm, đóng vai trò là nguồn sử liệu chân thực minh chứng cho đời sống tín ngưỡng và lịch sử hình thành lâu đời của vùng đất Đông Dương.  

Giá trị gắn kết cộng đồng: Khơi dậy nét đẹp nghệ thuật qua các đêm văn nghệ quần chúng, hát giao duyên quan họ trên thuyền và hát chèo. Các trò chơi dân gian và nghi thức lễ hội tạo không gian vui chơi lành mạnh đầu xuân, đóng vai trò là sợi dây gắn kết tinh thần, giúp cố kết tình cảm của những người con quê hương mỗi dịp tụ họp.', NULL, NULL, NULL, N'Lễ hội làng Đông Dương có từ xa xưa và được cộng đồng lưu giữ, duy trì tồn tại ổn định cho đến ngày nay. Tâm điểm tâm linh của di sản gắn liền với tín ngưỡng thờ phụng nhị vị Đương cảnh thành hoàng là Đô Minh Vương và Đương Cảnh thành hoàng theo ngọc phả của làng. Chiều sâu lịch sử và nền tảng phong kiến của di sản hiện còn được chứng thực qua 11 đạo sắc phong gốc thời phong kiến lưu giữ tại đình Đông Dương, dù một số bản đã bị rách mủn do thời gian và chưa được dịch nghĩa. Nhằm thể hiện sự tôn kính tuyệt đối đối với các vị thần, dân làng có tập tục nghiêm ngặt là kiêng đặt tên cho con cháu trùng với các từ: Sơn, Thủy, Long, Súy (nếu phạm phải gọi là sái).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The Dong Duong Village Festival originated in ancient times and has been stably preserved and maintained by the community to this day. The spiritual core of the heritage is tied to the worship of two local Tutelary Gods, Do Minh Vuong and Duong Canh Thanh Hoang, as recorded in the village''s sacred genealogy (ngoc pha). The historical depth and feudal foundations of the heritage are authenticated by 11 original royal certificates (sac phong) from the feudal era kept at the Dong Duong Communal House, though some have degraded over time and remain untranslated. To show absolute reverence to the deities, the villagers observe a strict taboo against naming their children after the words: Son, Thuy, Long, and Suy (violating this rule is considered a spiritual offense).', N'Spiritual and Cultural Value: Deeply educates on the traditional Vietnamese ethos of "When drinking water, remember its source," providing an occasion for locals to express reverence and gratitude to the deities while praying for peace and prosperity.  

Historical and Documentary Value: Preserves 11 ancient royal certificates and a rare sacred genealogy, serving as authentic historical records that demonstrate the long-standing spiritual life and historical background of the Dong Duong region.  

Community Bonding Value: Promotes artistic beauty through community performance nights, Quan ho love duets on boats, and Cheo singing. The traditional folk games and festival rituals offer a wholesome early spring recreational space, acting as a spiritual bond that strengthens the solidarity of villagers and returning expatriates alike.', N'The heritage is stably preserved in modern life and faces no risk of erosion. The festival maintains a large, well-organized practice force with approximately 150 active practitioners and 60 security supporters. The structured teams include a male ritual team (24 elders aged 60–70+ meeting strict purity standards), a palanquin procession team (16 unmarried young men aged 18–30), a Senh Tien musical team (12 members), and a unicorn dance team (8 members). The village currently has 2 master artisans, one of whom is actively passing down traditional knowledge to 20 apprentices through oral transmission.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (24, N'ih0024', N'Lễ hội truyền thống thôn Đoàn Xá (Hội làng Đoàn Xá)', N': Doan Xa Village Traditional Festival', N'festival', N'Lễ hội truyền thống thôn Đoàn Xá (xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể đặc sắc có lịch sử lâu đời, được tổ chức lớn 3 năm một lần từ ngày mùng 9 đến ngày 11 tháng Giêng Âm lịch. Lễ hội diễn ra trong không gian văn hóa rộng lớn gồm đình làng, các đền và quán để phụng thờ các vị công chúa, Lạc tướng Quan lang có công và Thánh mẫu Liễu Hạnh. Sự kiện quy tụ nhiều nghi lễ tâm linh trang trọng như lễ rước bát hương và thần bằng 4 cỗ kiệu từ các đền quán về đình làng, lễ tế Quan hưng niên, tế Hội đồng và tiệc khai xuân gắn kết với các làng lân cận. Phần hội rộn ràng với các hoạt động múa rồng lân, chơi cờ tướng, đập niêu, bắt vịt và hát sướng, góp phần thắt chặt tình làng nghĩa xóm, cố kết tình cảm gia đình và lưu giữ bản sắc quê hương.', N'Doan Xa Village Traditional Festival (Van Dinh Commune, Hanoi) is a distinctive intangible cultural heritage with a long history, celebrated on a grand scale every three years from the 9th to the 11th day of the first lunar month. The festival takes place across an expansive cultural space including the communal house, shrines, and temples to worship meritorious princesses, historic generals (Lac Tuong), and Holy Mother Lieu Hanh. The event features solemn spiritual rituals such as a grand procession carrying 4 palanquins of incense burners and deities from various shrines to the central communal house, offering ceremonies, and a springtime opening feast that connects neighboring villages. The festive section is vibrant with dragon and unicorn dances, Chinese chess, pot-smashing, duck-catching, and traditional singing (hat suong), strengthening community solidarity and family affection while preserving local identity.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T18:59:47.9759701', NULL, 2, NULL, NULL, NULL, N'Di sản đang được bảo tồn ổn định theo tiêu chuẩn quy ước nông thôn mới và không có nguy cơ mai một. Lễ hội duy trì lực lượng thực hành bài bản, đông đảo gồm 150 người thực hành và 60 người hỗ trợ bảo vệ. Cơ cấu nhân sự tham gia rất chặt chẽ với ban tế lễ 40 người (đội tế nam và đội tế nữ trên 60 tuổi), đội rồng lân (32 người), đội rước cờ bát bửu (30 người trung niên) và 40 thanh niên rước kiệu. Làng hiện có 1 nghệ nhân còn khả năng và đang tích cực thực hiện truyền dạy trực tiếp theo phương thức truyền miệng cho 20 học viên.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị nhân văn & đạo đức: Thể hiện sâu sắc truyền thống "Uống nước nhớ nguồn", bày tỏ lòng thành kính và tri ân đối với các bậc thánh thần và tiền nhân có công với dân với nước, từ đó giáo dục cội nguồn cho thế hệ sau.  

Giá trị lịch sử & tư liệu cổ: Lưu giữ khối lượng tư liệu dịch thuật thần tích, thần phả từ thế kỷ XIV, XVI cùng các đạo sắc phong quý giá của hai triều đại Lê - Nguyễn, là nguồn sử liệu quan trọng khẳng định bề dày lịch sử địa phương.  

Giá trị văn hóa & cố kết cộng đồng: Khơi dậy nét đẹp diễn xướng dân gian qua các điệu hát sướng đầu xuân và múa rồng lân. Đồng thời, tiệc khai xuân kết nghĩa với 5 thôn lân cận và các trò chơi dân gian tạo không gian giao lưu lành mạnh, giúp nhân dân quy tụ, gặp gỡ và cố kết bền chặt tình cảm gia đình, làng xóm.', NULL, NULL, NULL, N'Theo tư liệu lịch sử, lễ hội làng Đoàn Xá xuất hiện từ tháng Giêng năm Canh Tý (năm 1920 - năm thứ 4 niên hiệu Khải Định). Chiều sâu lịch sử của di sản gắn liền với các bản thần tích, thần phả từ thế kỷ XIV và XVI, cùng hệ thống sắc phong của các triều đại nhà Lê và nhà Nguyễn. Lễ hội phụng thờ quần thể các vị thần, thánh có công lớn với đất nước gồm: Quốc mẫu vua bà đệ nhất tiên công chúa; Đệ nhị quế hoa công chúa (Mị Nữ Quế Hoa); hai vị Lạc Tướng Quan Lang là Báo Đức Đại Vương và Huệ An Đại Vương; Trung Đẳng Thần; Quí Minh Đại Tướng (thời Hùng Vương thứ 18); và đặc biệt là 7 đạo sắc phong Thánh mẫu Liễu Hạnh làm Thành hoàng làng. Nhằm đảm bảo sự trang nghiêm, làng giữ quy ước nghiêm ngặt kiêng kỵ không để những gia đình đang có tang sự tham gia vào Ban tổ chức lễ hội.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'According to historical records, the Doan Xa Village Festival originated in the first lunar month of the Canh Ty year (1920, the 4th year of the Khai Dinh reign). The historical depth of the heritage is linked to divine annals and historical records dating back to the 14th and 16th centuries, alongside royal certificates from the Le and Nguyen dynasties. The festival venerates a pantheon of deities who made great contributions to the nation, including: the First Princess National Mother; the Second Que Hoa Princess; two Lac Tuong generals (Bao Duc Dai Vuong and Hue An Dai Vuong); a Medium-rank Deity; General Quy Minh (from the 18th Hung King era); and notably 7 royal certificates installing Holy Mother Lieu Hanh as the village Tutelary Goddess. To ensure solemnity, the village strictly observes a taboo prohibiting individuals from families in mourning from joining the festival organizing committee.', N'Humanistic & Ethical Value: Deeply reflects the traditional Vietnamese ethos of "When drinking water, remember its source," expressing reverence and gratitude to deities and ancestors with great merits, thereby educating future generations about their roots.  

Historical & Documentary Value: Preserves a massive volume of translated divine annals and records from the 14th and 16th centuries, along with precious royal certificates from the Le and Nguyen dynasties, serving as vital historical evidence verifying local history.  

Cultural & Community Bonding Value: Revives folk performing arts through springtime traditional singing (hat suong) and dragon-unicorn dances. Furthermore, the spring alliance feast with 5 neighboring villages and folk games provide a wholesome space for social interaction, helping people gather and tighten family and community bonds.', N'The heritage is stably preserved according to the New Rural Area conventions and faces no risk of erosion. The festival maintains a well-structured and large practice force comprising 150 active practitioners and 60 security protectors. The personnel structure is strictly organized, including a 40-member ritual team (male and female teams aged 60+), a dragon-unicorn dance team (32 members), a banner and weapon procession team (30 middle-aged members), and 40 young men bearing the palanquins. The village currently has 1 master artisan who is actively passing down traditional knowledge to 20 apprentices through oral transmission.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (25, N'ih0025', N'Lễ hội truyền thống thôn Cao Lãm (Hội làng Cao Lãm)', N'Cao Lam Village Traditional Festival', N'festival', N'Lễ hội truyền thống thôn Cao Lãm (xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể mang tính cộng đồng sâu sắc, có lịch sử lâu đời và được tổ chức định kỳ 3 năm một lần vào ngày mùng 9 và mùng 10 tháng Giêng Âm lịch (chính hội vào ngày mùng 10). Lễ hội diễn ra tập trung tại đình làng Cao Lãm nhằm phụng thờ hai vị Thành hoàng là Long Vương Linh Thông Hiển Ứng Đại Vương Thượng Đẳng Thần và Trang Thuần Trinh Thục Công Chúa. Sự kiện quy tụ các nghi lễ tâm linh trang trọng với sự tham gia bài bản của đội tế nam, đội dâng hương nữ cùng các đội rước, đội nhạc, đội trống, đội rồng và đội bát bửu. Lễ hội là không gian văn hóa đặc sắc thắt chặt tình đoàn kết xóm làng và gìn giữ nét đẹp tín ngưỡng truyền thống của địa phương.', N'Cao Lam Village Traditional Festival (Van Dinh Commune, Hanoi) is a deep-rooted community intangible cultural heritage with a long history, celebrated periodically every three years on the 9th and 10th days of the first lunar month, with the main festival falling on the 10th. Centered at Cao Lam Communal House, the festival venerates two Tutelary Gods: Long Vuong Linh Thong Hien Ung Dai Vuong Thuong Dang Than and Trang Thuan Trinh Thuc Princess. The event features solemn spiritual rituals with well-structured participation from the male ritual team, female incense offering team, alongside procession teams, musical and drumming squads, a dragon dance team, and a ceremonial weapons (bat buu) team. The festival offers a unique cultural space that strengthens community solidarity and preserves local traditional beliefs.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T19:01:23.9130051', NULL, 2, NULL, NULL, NULL, N'Di sản đang được lưu giữ và thực hành ổn định trong đời sống nhân dân thôn Cao Lãm. Lực lượng tham gia hành lễ được phân công vô cùng cụ thể, quy củ về cả số lượng, độ tuổi và trang phục truyền thống. Các đội hình bao gồm: Đội tế nam (17 người từ 40 tuổi trở lên), Đội dâng hương nữ (13 người từ 35 tuổi trở lên), Đội rước nam (16 người từ 25 tuổi trở lên), Đội rước nữ (8 người từ 20 tuổi trở lên), Đội nhạc (8 người), Đội trống (4 người), Đội rồng (18 người) và Đội bát bửu (8 thành viên được tuyển chọn từ Hội cựu chiến binh của thôn). Việc chuẩn bị trang phục nghiêm ngặt (áo lậu đỏ, áo dài the, đai đỏ, áo lính lệ) phản ánh ý thức bảo tồn di sản rất cao của cộng đồng.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị văn hóa tâm linh: Đáp ứng nhu cầu đời sống tinh thần của nhân dân, giúp cộng đồng bày tỏ lòng tôn kính, biết ơn sâu sắc đối với các vị Thành hoàng làng và cầu mong mưa thuận gió hòa, bình an cho xóm làng.  

Giá trị lịch sử & giáo dục: Gìn giữ tín ngưỡng thờ thần, thánh mang đậm bản sắc văn hóa vùng đồng bằng Bắc Bộ, góp phần giáo dục truyền thống "Uống nước nhớ nguồn" và lòng tự hào quê hương cho các thế hệ.  

Giá trị gắn kết cộng đồng: Huy động sự tham gia đông đảo của mọi tầng lớp nhân dân, từ các cụ cao tuổi, hội cựu chiến binh đến nam thanh nữ tú trong làng thông qua các vai trò hành lễ, rước kiệu bài bản, tạo nên sự cố kết cộng đồng bền chặt.', NULL, NULL, NULL, N'Lễ hội làng Cao Lãm là lễ hội truyền thống được lưu truyền lâu đời trong đời sống của nhân dân địa phương. Tâm điểm tâm linh và cội nguồn của lễ hội gắn liền với tín ngưỡng thờ phụng hai vị Thành hoàng làng có công trạng hiển hách bao gồm: Long Vương Linh Thông Hiển Ứng Đại Vương Thượng Đẳng Thần (vị thần tối cao) và Trang Thuần Trinh Thục Công Chúa. Các nghi thức tế lễ và rước xách trong lễ hội đều hướng về việc tri ân, tưởng nhớ công đức của hai vị thần đối với cuộc sống của người dân thôn Cao Lãm.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The Cao Lam Village Festival is a traditional festival passed down through generations in the lives of the local people. The spiritual core and origin of the festival are closely associated with the worship of two meritorious village Tutelary Gods, including: Long Vuong Linh Thong Hien Ung Dai Vuong Thuong Dang Than (a supreme deity) and Trang Thuan Trinh Thuc Princess. The offering and procession rituals during the festival are heavily dedicated to expressing gratitude and commemorating the divine contributions of these two deities to the lives of Cao Lam villagers.', N'Spiritual and Cultural Value: Satisfies the local community''s spiritual needs, allowing the residents to express deep reverence and gratitude to the Tutelary Gods while praying for favorable weather, peace, and prosperity.  

Historical and Educational Value: Preserves the worship of deities rooted in the cultural identity of the Northern Delta, contributing to educating generations about the traditional ethos of "When drinking water, remember its source" and local pride.  

Community Bonding Value: Mobilizes massive participation from all social strata, including village elders, the veterans'' association, and young men and women through well-organized ritual and procession roles, fostering tight community solidarity.', N'The heritage is stably preserved and practiced in the daily life of Cao Lam villagers. The ritual forces are assigned with high specificity and organization regarding numbers, age groups, and traditional costumes. The structured teams consist of: a male ritual team (17 members aged 40+), a female incense offering team (13 members aged 35+), a male procession team (16 members aged 25+), a female procession team (8 members aged 20+), a musical team (8 members), a drumming team (4 members), a dragon dance team (18 members), and a ceremonial weapons (bat buu) team (8 members selected from the village Veterans'' Association). The strict management of ceremonial costumes (red dynamic robes, traditional gauze tunics, red sashes, and soldier uniforms) reflects the community''s high awareness of heritage preservation.', NULL);
INSERT [IntangibleHeritage] ([IntangibleId],[PublicId],[NameVi],[NameEn],[Category],[DescriptionVi],[DescriptionEn],[ImageUrl],[VideoUrl],[IsDeleted],[CreatedAt],[UpdatedAt],[CreatedBy],[UpdatedBy],[Community],[CulturalSpace],[CurrentStatus],[CustomsAndOfferings],[ExistingArtisans],[ExistingProtectionMeasures],[FestivalDuration],[FestivalLocation],[FestivalTime],[FolkGames],[FormationHistory],[GalleryImages],[HeritageValue],[HistoricalDevelopment],[Learners],[Location],[Origin],[OtherHumanResources],[OtherNames],[Practitioners],[ProposedProtectionMeasures],[RelatedDocuments],[RepresentativePersons],[RiskDescription],[RitualObjects],[RitualParticipants],[RitualProcess],[TeachingArtisans],[ThreatLevel],[TraditionalPerformances],[TransmissionMethod],[WorshipObjects],[OriginEn],[HeritageValueEn],[CurrentStatusEn],[RelatedDocumentsEn]) VALUES (26, N'ih0026', N'Hội quán Chài (Lễ hội truyền thống xóm 10, thôn Đoàn Xá)', N'Quan Chai Gathering Festival (Xom 10, Doan Xa Village Traditional Festival)', N'festival', N'Hội quán Chài (xóm 10, thôn Đoàn Xá, xã Vân Đình, Hà Nội) là di sản văn hóa phi vật thể lâu đời độc đáo, với ngày hội chính diễn ra vào mùng 4 tháng Giêng hằng năm. Tổ chức tại không gian Đình Quán Chài và Đền Mẫu Thủy, lễ hội phụng thờ thần Hà Bá, Đương cảnh thành hoàng cùng Tứ vị công chúa và Quốc mẫu. Di sản đặc trưng bởi quy trình thực hành sông nước nghiêm cẩn như lễ xin phép rước ngài về ăn Tết trên sông vào chiều 30 Tết, lễ rước thần hội cung, tế lễ trang nghiêm của các đội tế nam/nữ vào sáng mùng 4. Điểm nhấn đặc sắc của lễ hội là nghi thức rước thần bằng thuyền rồng kết hợp hát quan họ thờ ngài trên sông và hội đua bơi chải truyền thống đầy kịch tính giữa các khu xóm, tạo nên một không gian văn hóa đậm đà bản sắc sông nước, thắt chặt tình đoàn kết cộng đồng.', N'Quan Chai Gathering Festival (Xom 10, Doan Xa Village, Van Dinh Commune, Hanoi) is a unique and long-standing intangible cultural heritage, with its main festival held annually on the 4th day of the first lunar month. Hosted at Quan Chai Communal House and Mau Thuy Temple, the festival worships the River God (Ha Ba), the local Tutelary God, alongside four Princesses and the National Mother. The heritage is characterized by strict water-based rituals, such as the New Year invitation ceremony on boats on the afternoon of the 30th day of the last lunar month, and solemn offering rituals on the morning of the 4th. The most distinctive highlights include a sacred deity procession on dragon boats combined with ceremonial Quan ho singing on the river, and a thrilling traditional boat racing competition between local neighborhoods, creating a vibrant riverine cultural space that strengthens community solidarity.', N'/uploads/images/6bf390d892464232ba002c1d8fc92965.png', NULL, 0, '2026-07-10T19:02:55.3371748', NULL, 2, NULL, NULL, NULL, N'Di sản hiện đang được bảo tồn ổn định trong đời sống nhân dân và không có nguy cơ mai một. Hoạt động lễ hội chủ yếu tổ chức theo tập tục truyền miệng do các cụ để lại nhưng có sự phân công lực lượng tham gia vô cùng chặt chẽ và quy củ. Lực lượng thực hành duy trì khoảng 100 người và 40 người thuộc nguồn lực bảo vệ khác. Cơ cấu nhân sự bao gồm đội tế nam (24 cụ ông trên 60 tuổi), đội tế nữ (24 cụ bà trên 60 tuổi), đội rước nam (43 thanh niên chưa vợ), đội rước nữ (16 thiếu nữ chưa chồng) cùng các đội rước kiệu, múa sênh tiền và ban nhạc bát âm. Hiện làng có 3 nghệ nhân, trong đó 1 người còn khả năng và đang tích cực truyền dạy trực tiếp theo phương thức truyền miệng cho 15 học viên. Các đội bơi chải (14 người/thuyền) của hai khu xóm vẫn tập luyện và thi đấu đều đặn hằng năm.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Giá trị văn hóa tâm linh & Đạo đức: Giáo dục sâu sắc đạo lý "Uống nước nhớ nguồn", bày tỏ lòng biết ơn tổ tiên và các bậc tiền nhân có công; giữ gìn trật tự, đạo đức, hiếu nghĩa và nếp sống nhân văn trước sự xô bồ của lối sống thực dụng.  

Giá trị lịch sử & tư liệu cổ: Lưu giữ các đạo sắc phong quý hiếm thời Nguyễn của nhiều triều vua phong kiến, là nguồn sử liệu chân thực chứng minh lịch sử hình thành lâu đời và tín ngưỡng thờ thần sông nước gắn liền với sinh kế của cư dân địa phương.  

Giá trị thể thao & gắn kết cộng đồng: Bảo tồn hội đua bơi chải truyền thống đặc sắc trên sông và nghệ thuật diễn xướng hát quan họ trên thuyền rồng. Các hoạt động tập thể này là sợi dây thắt chặt tình đoàn kết cộng đồng dân cư xóm làng, tạo không khí thi đua sôi nổi đầu xuân.', NULL, NULL, NULL, N'Lễ hội quán Chài có từ xa xưa rất lâu đời và được cộng đồng nhân dân duy trì, lưu truyền bền vững qua nhiều thế hệ. Nguồn gốc tâm linh của lễ hội gắn liền với hệ thống thờ tự các vị thần sông nước và thành hoàng bảo an gồm: thần Hà Bá; Đương cảnh thành hoàng Quốc Vương Quyền Tri Giang Hải tôn thần; cùng Tứ vị (Hoàng Nương, Hoàng phi công chúa, Cấp Thủy Tinh công chúa và Quốc Mẫu vua bà). Chiều sâu lịch sử và nền tảng phong kiến của di sản được ghi nhận qua hệ thống sắc phong thời Nguyễn lưu giữ tại di tích, bao gồm các đạo sắc phong của các đời vua Tự Đức, Đồng Khánh, Duy Tân, Khải Định ban cho thần Hà Bá, và vua Thành Thái, Khải Định ban cho vị Thành hoàng làng (hiện đình còn lưu giữ 4 đạo sắc phong chưa dịch nghĩa). Nhằm giữ gìn tính tôn nghiêm, lễ hội giữ quy ước kiêng kỵ nghiêm ngặt không để các cụ ông có tang bụi tham gia vào đội hình tế lễ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'The Quan Chai Gathering Festival originated in ancient times and has been sustainably maintained and transmitted by the community across generations. The spiritual origin of the festival is closely linked to the worship of water deities and protective tutelary gods, including: the River God (Ha Ba); the local Tutelary God governing rivers and seas; and the Four Goddesses (Hoang Nuong, Princess Royal Concubine, Princess Cap Thuy Tinh, and the National Mother). The historical depth and feudal foundations of the heritage are documented through the Nguyen Dynasty royal certificates (sac phong) preserved at the site, including those bestowed upon the River God by Kings Tu Duc, Dong Khanh, Duy Tan, and Khai Dinh, as well as those granted to the Tutelary God by Kings Thanh Thai and Khai Dinh (4 untranslated royal certificates are currently stored at the communal house). To maintain strict solemnity, the community observes a taboo prohibiting men whose families are in mourning from joining the ritual team.', N'Spiritual, Cultural & Ethical Value: Deeply instills the traditional Vietnamese ethos of "When drinking water, remember its source," expressing gratitude to ancestors and meritorious pioneers; it preserves order, morality, filial piety, and a humanistic lifestyle against the hustle of pragmatic modern living.  

Historical & Documentary Value: Preserves rare Nguyen Dynasty royal certificates across multiple reigns, serving as authentic historical evidence of the ancient origins and water-deity worship linked to the livelihoods of local residents.  

Sporting & Community Bonding Value: Safeguards the distinctive traditional boat racing festival on the river and the performing art of Quan ho singing on dragon boats. These collective activities act as a vital bond tightening community solidarity and creating a lively competitive spirit in early spring.', N'The heritage is currently stably preserved in the daily life of the people and faces no risk of erosion. Although the festival operations rely mainly on oral traditions passed down by ancestors, the assignment of participating forces is highly structured and disciplined. The practice force maintains around 100 active individuals and 40 other protective personnel. The personnel structure consists of a male ritual team (24 elders aged 60+), a female ritual team (24 elders aged 60+), a male procession team (43 unmarried young men), a female procession team (16 unmarried young women), alongside palanquin bearers, Senh Tien dancers, and a 10-member traditional orchestra. There are currently 3 master artisans, one of whom is actively passing down traditional knowledge to 15 apprentices through oral transmission. The boat racing teams (14 members per boat) from both neighborhoods continue to practice and compete regularly every year.', NULL);
